function bindDelegatedActions() {
  if (document.body.dataset.delegatedActionsBound) return;
  document.body.dataset.delegatedActionsBound = "true";
  document.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    const actions = {
      generateItinerary: handleGenerateItinerary,
      aiImportItinerary: handleAiImportItinerary,
      loadHistory: handleLoadHistory,
      addDay: handleAddDay,
      buildProposal: handleBuildProposal,
      exportPdf: handleExportPdf,
      exportImage: handleExportImage,
      saveVersion: handleSaveVersion,
      agentRecognizeDemand,
      agentApplyCustomer,
      agentCheckMissing,
      agentFollowQuestions,
      agentGenerateRoute,
      agentOptimizeRoute,
      agentConfirmRoute,
      agentExtractQuoteItems,
      agentApplyQuoteItems,
      agentRecalculateQuote,
      agentCheckCosts,
      agentBuildCustomerProposal,
      agentCheckEnglish,
      agentSaveQuoteVersion,
      confirmProposal,
    };
    const action = actions[button.id];
    if (button.dataset.agentApply) {
      event.preventDefault();
      event.stopPropagation();
      applyCurrentAgentPending();
      return;
    }
    if (button.dataset.agentIgnore) {
      event.preventDefault();
      event.stopPropagation();
      setAgentPending("message", { title: "已忽略 AI 建议", body: "未对正式页面数据做任何修改。" });
      return;
    }
    if (button.dataset.xiaoyiAction) {
      event.preventDefault();
      event.stopPropagation();
      applyXiaoyiAction(button.dataset.xiaoyiAction, Number(button.dataset.xiaoyiMessage));
      return;
    }
    if (button.dataset.xiaoyiIgnore) {
      event.preventDefault();
      event.stopPropagation();
      addXiaoyiMessage("assistant", "已忽略这条建议，没有改动正式页面数据。");
      return;
    }
    if (button.dataset.syncQuoteRow) {
      event.preventDefault();
      event.stopPropagation();
      openSyncQuoteItemModal(button.dataset.syncQuoteRow);
      return;
    }
    if (button.dataset.openQuotableSelector) {
      event.preventDefault();
      event.stopPropagation();
      openQuotableResourceSelector(button.dataset.openQuotableSelector);
      return;
    }
    if (button.dataset.rematchQuoteRow) {
      event.preventDefault();
      event.stopPropagation();
      rematchQuoteRow(button.dataset.rematchQuoteRow);
      return;
    }
    if (button.dataset.currentOnlyRow) {
      event.preventDefault();
      event.stopPropagation();
      markQuoteRowCurrentOnly(button.dataset.currentOnlyRow);
      return;
    }
    if (button.dataset.applyRouteSuggestion) {
      event.preventDefault();
      event.stopPropagation();
      applySuggestedRouteOrder();
      return;
    }
    if (button.dataset.fixResidue) {
      event.preventDefault();
      event.stopPropagation();
      fixSingleResidue(button.dataset.fixResidue);
      return;
    }
    if (button.dataset.editResidue) {
      event.preventDefault();
      event.stopPropagation();
      openTranslationEditModal(button.dataset.editResidue);
      return;
    }
    if (button.dataset.markCleanRow) {
      event.preventDefault();
      event.stopPropagation();
      markQuoteRowPendingClean(button.dataset.markCleanRow);
      return;
    }
    if (!action) return;
    event.preventDefault();
    event.stopPropagation();
    action();
  }, true);
}

function applyCurrentAgentPending() {
  const type = state.agent.pendingType;
  if (type === "customer") return agentApplyCustomer();
  if (type === "route") return agentConfirmRoute();
  if (type === "quoteItems") return agentApplyQuoteItems();
  if (type === "customerProposal") {
    applyCustomerProposal(state.agent.pendingData);
    return setAgentPending("message", { title: "已应用客户版报价文案", body: "客户提案预览已更新，导出前请人工确认方案。" });
  }
  return setAgentPending("message", { title: "当前建议无需应用", body: "这是检查或提示信息，不会写入正式页面字段。" });
}

