  ensureTemplateSheetReport(report, sheetName, category);
  const labels = ["城市", "景点名称", "类型", "票种", "淡季成人", "淡季儿童", "旺季成人", "旺季儿童", "旅行社成人", "旅行社儿童", "免费政策", "备注", "保票政策", "保票联系人姓名", "保票联系人电话"];
  let currentCity = "";
