function useRouteProductInQuote(id) {
  const route = routeProductById(id);
  if (!route) return;
  state.selectedRouteProductId = route.routeProductId || route.code;
  $("#cities").value = route.city || $("#cities").value;
  $("#serviceDays").value = route.days || 1;
  const includes = route.includes || [];
  const serviceMap = [
    ["svcVehicle", /用车|接送|包车|交通/],
    ["svcTickets", /景点|门票|故宫|长城|寺|湖|古镇|博物/],
    ["svcGuide", /导游|讲解/],
    ["svcHotel", /酒店|住宿/],
    ["svcMeals", /餐|午餐|晚餐|早餐/],
    ["svcTraffic", /大交通|火车|高铁|飞机/],
    ["svcOther", /保险|耳麦|水|伴手礼|特色体验/],
  ];
  serviceMap.forEach(([idName, pattern]) => {
    const node = $(`#${idName}`);
    if (node) node.checked = includes.some((item) => pattern.test(item));
  });
  if (!number($("#adults").value) && !number($("#children").value)) $("#adults").value = 2;
  syncItineraryToDemand();
  handleGenerateItinerary();
  buildQuote();
  switchModule("quote");
  alert(`已带入线路产品「${route.name}」，报价明细会按 ${route.routeProductId || route.code} 的成本档位追溯。`);
}
