function quoteRowActions(service, index) {
  return `<div class="row-actions quote-row-actions">
    <button class="primary-btn" data-open-quotable-selector="${service}:${index}">从资源库选择</button>
    <button class="secondary-btn" data-rematch-quote-row="${service}:${index}">重新匹配</button>
    <button class="secondary-btn" data-sync-quote-row="${service}:${index}">同步产品库</button>
    <button class="ghost-btn" data-current-only-row="${service}:${index}">仅当前报价</button>
    <button class="ghost-btn" data-mark-clean-row="${service}:${index}">待清洗</button>
  </div>`;
}

function parseQuoteRowToken(token) {
  const [service, indexText] = String(token || `${state.activeService}:0`).split(":");
  return { service: service || state.activeService, index: Number(indexText || 0) };
}

function quoteRowByToken(token) {
  const { service, index } = parseQuoteRowToken(token);
  const row = activeQuote().data?.[service]?.[index];
  return { service, index, row, day: state.itinerary[service === "vehicle" ? (row?.dayIndex ?? index) : index] || {} };
}

function quoteServiceCategory(service) {
  return ({ vehicle: "包车", guide: "导游", ticket: "门票", hotel: "酒店", meal: "餐", traffic: "大交通", other: "其他", experience: "特色体验" })[service] || "其他";
}

function quoteRowResourceQuery({ service, row, day }) {
  const category = quoteServiceCategory(service);
  const d = getDemandSafe();
  const city = row?.city || day?.city || "";
  const keyword = [
    row?.productName,
    row?.sourceName,
    row?.legLabel,
    row?.route,
    row?.serviceType,
    service === "ticket" ? row?.items?.map((item) => item.name).join(" ") : "",
    service === "hotel" ? row?.rooms?.map((room) => `${room.hotelName || ""} ${room.roomType || ""}`).join(" ") : "",
  ].filter(Boolean).join(" ");
  return {
    category,
    city,
    keyword,
    serviceCategory: service === "vehicle" ? row?.serviceType : "",
    vehicleModel: service === "vehicle" ? row?.model : "",
    language: service === "guide" ? d.guideLang : "",
    roomType: service === "hotel" ? row?.rooms?.[0]?.roomType : "",
    ticketType: service === "ticket" ? row?.items?.[0]?.ticketType : "",
    routeName: service === "vehicle" ? row?.route || row?.legLabel : "",
  };
}

function openQuotableResourceSelector(token = `${state.activeService}:0`) {
  const data = quoteRowByToken(token);
  if (!data.row) {
    alert("当前报价行不存在，无法选择资源。");
    return;
  }
  refreshV14ResourceState();
  const query = quoteRowResourceQuery(data);
  let resources = queryQuotableResources(query);
  if (!resources.length) resources = queryQuotableResources({ category: query.category, city: query.city });
  if (!resources.length) resources = queryQuotableResources({ category: query.category });
  const modal = ensureQuotableResourceSelectorModal();
  modal.querySelector("[data-quotable-body]").innerHTML = `
    <div class="sync-preview-grid">
      ${[
        ["服务项", serviceLabels[data.service] || data.service],
        ["城市", query.city || "待补城市"],
        ["筛选品类", query.category],
        ["关键词", query.keyword || "-"],
      ].map(([label, value]) => `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong></div>`).join("")}
    </div>
    <div class="quotable-resource-list">
      ${resources.slice(0, 30).map((resource) => renderQuotableResourceOption(resource, token)).join("") || `<div class="empty">没有找到可报价资源。请先在供应商管理里补服务明细，或在产品资源详情里关联供应商。</div>`}
    </div>`;
  modal.classList.remove("hidden");
  modal.querySelectorAll("[data-select-quotable-resource]").forEach((btn) => btn.addEventListener("click", () => applyQuotableResourceToQuoteRow(btn.dataset.selectQuotableResource, btn.dataset.quoteRowToken)));
  renderIcons();
}

function renderQuotableResourceOption(resource, token) {
  const cost = resource.costPrice === "" || resource.costPrice == null ? "待补成本" : money(resource.costPrice);
  const statusText = ({ valid: "有效", expiring_soon: "即将过期", expired: "已过期", no_validity: "无有效期" })[resource.priceStatus] || "待确认";
  const risk = resource.riskFlags?.length ? `<span class="danger-text">${escapeHtml(resource.riskFlags.join(" / "))}</span>` : `<span class="ok-text">可选</span>`;
  return `<div class="resource-option">
    <div>
      <strong>${escapeHtml(resource.title || resource.name)}</strong>
      <span>${escapeHtml(resource.category)} · ${escapeHtml(resource.city || "-")} · ${escapeHtml(resource.supplierName || IMPORTED_PENDING_SUPPLIER)}</span>
      <small>${escapeHtml(resource.serviceCategory || resource.routeName || resource.language || resource.roomType || resource.ticketType || "")}</small>
    </div>
    <div>
      <strong>${cost}</strong>
      <span>${escapeHtml(statusText)}${resource.matchScore ? ` · 分数 ${resource.matchScore}` : ""}</span>
      ${risk}
    </div>
    <button class="primary-btn" data-select-quotable-resource="${escapeHtml(resource.id)}" data-quote-row-token="${escapeHtml(token)}">选择</button>
  </div>`;
}

function ensureQuotableResourceSelectorModal() {
  let modal = $("#quotableResourceSelectorModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "quotableResourceSelectorModal";
  modal.className = "modal-backdrop hidden";
  modal.innerHTML = `<div class="modal-card wide-modal"><div class="modal-head"><div><h3>从资源库选择供应商资源</h3><p>只回填产品库或供应商服务明细里的成本，AI 不参与定价。</p></div><button class="icon-btn" data-close-quotable-selector aria-label="关闭"><i data-lucide="x"></i></button></div><div class="modal-body" data-quotable-body></div></div>`;
  document.body.appendChild(modal);
  modal.querySelector("[data-close-quotable-selector]").addEventListener("click", () => modal.classList.add("hidden"));
  return modal;
}

function applyQuotableResourceToQuoteRow(resourceId, token) {
  const data = quoteRowByToken(token);
  const resource = (state.quotableResources || []).find((item) => item.id === resourceId);
  if (!data.row || !resource) return;
  if (resource.priceStatus === "expired") {
    alert("该资源价格已过期，不能直接进入报价。请先更新供应商服务明细有效期。");
    return;
  }
  if (resource.priceStatus === "no_validity") {
    const ok = window.confirm("该资源没有价格有效期，是否人工确认后用于当前报价？");
    if (!ok) return;
  }
  const snapshot = quotableCore()?.createQuoteLineSnapshot(resource, {
    productResourceId: resource.productResourceIds?.[0] || "",
    selectedBy: state.currentRole || "admin",
  }) || {};
  writeResourceSnapshotToQuoteTarget(data, resource, snapshot);
  recordOperationLog("quote_line_resource_selected", {
    quoteRow: token,
    supplierId: resource.supplierId,
    supplierName: resource.supplierName,
    serviceDetailId: resource.serviceDetailId,
    resourceId: resource.id,
    costPriceSnapshot: snapshot.costPriceSnapshot,
  });
  saveQuoteVersions();
  const modal = $("#quotableResourceSelectorModal");
  if (modal) modal.classList.add("hidden");
  renderQuoteTable();
  renderQuoteTabs();
  renderSummary();
}

function writeResourceSnapshotToQuoteTarget(data, resource, snapshot) {
  const cost = valueOrEmpty(snapshot.costPriceSnapshot ?? resource.costPrice);
  const common = {
    sourceType: "供应商服务明细",
    sourceProductId: snapshot.sourceProductId || resource.sourceProductId || "",
    sourceResourceId: snapshot.sourceResourceId || resource.id || "",
    sourceName: resource.title || resource.name,
    supplierId: resource.supplierId || "",
    supplierName: resource.supplierName || IMPORTED_PENDING_SUPPLIER,
    serviceDetailId: resource.serviceDetailId || "",
    serviceDetailName: resource.title || resource.name,
    costSource: "供应商服务明细",
    quoteLineSnapshot: snapshot,
    matchStatus: cost === "" ? "need_price" : (resource.priceStatus === "no_validity" ? "need_confirm" : "matched"),
    matchReason: cost === "" ? "成本价为空" : (resource.priceStatus === "no_validity" ? "价格无有效期，已人工确认" : "人工选择供应商资源"),
    missingCost: cost === "",
    source: `供应商服务明细 / ${resource.supplierName || IMPORTED_PENDING_SUPPLIER} / ${resource.title || resource.name}`,
  };
  if (data.service === "vehicle") {
    Object.assign(data.row, common, {
      city: resource.city || data.row.city,
      serviceType: resource.serviceCategory || data.row.serviceType,
      route: resource.routeName || resource.route || data.row.route,
      model: resource.model || resource.vehicleModel || data.row.model,
      productName: resource.title || resource.name,
      charterCost: cost,
      unitCost: cost,
      totalCost: cost,
      salePrice: cost === "" ? "" : sellMargin(cost),
      totalSale: cost === "" ? "" : sellMargin(cost),
    });
    return;
  }
  if (data.service === "guide") {
    Object.assign(data.row, common, {
      serviceCost: cost,
      unitCost: cost,
      totalCost: cost,
      salePrice: cost === "" ? "" : sellMargin(cost),
      totalSale: cost === "" ? "" : sellMargin(cost),
    });
    return;
  }
  if (data.service === "meal") {
    Object.assign(data.row, common, {
      perPersonCost: cost,
    });
    return;
  }
  if (data.service === "traffic") {
    Object.assign(data.row, common, {
      adultCost: cost,
      childCost: valueOrEmpty(resource.childCost || ""),
    });
    return;
  }
  if (data.service === "ticket") {
    const item = data.row.items?.find((candidate) => candidate.missingCost || candidate.adultCost === "") || data.row.items?.[0];
    if (item) Object.assign(item, common, {
      name: resource.title || item.name,
      adultCost: cost,
      childCost: valueOrEmpty(resource.childCost || item.childCost || ""),
      unitCost: cost,
      totalCost: cost === "" ? "" : number(cost) * getDemandSafe().adults + number(resource.childCost || item.childCost) * getDemandSafe().children,
      salePrice: cost === "" ? "" : sellMargin(cost),
    });
    data.row.missingCost = (data.row.items || []).some((candidate) => candidate.missingCost || candidate.adultCost === "");
    return;
  }
  if (data.service === "hotel") {
    const room = data.row.rooms?.find((candidate) => candidate.missingCost || candidate.unitCost === "") || data.row.rooms?.[0];
    if (room) Object.assign(room, common, {
      hotelName: resource.title || room.hotelName,
      roomType: resource.roomType || room.roomType,
      unitCost: cost,
      totalCost: cost === "" ? "" : number(cost) * number(room.rooms || 1),
      salePrice: cost === "" ? "" : sellMargin(cost),
    });
    data.row.missingCost = (data.row.rooms || []).some((candidate) => candidate.missingCost || candidate.unitCost === "");
    return;
  }
  Object.assign(data.row, common, {
    routeProductUnitCost: cost,
  });
}

function openSyncQuoteItemModal(token = `${state.activeService}:0`) {
  const data = quoteRowByToken(token);
  if (!data.row) {
    alert("当前服务项没有可同步的报价行。");
    return;
  }
  const product = quoteRowToProduct(data);
  const missing = productMissingFields(product, product.category);
  const modal = ensureQuoteSyncModal();
  modal.querySelector("[data-sync-body]").innerHTML = `
    <div class="sync-preview-grid">
      ${[
        ["品类", product.category],
        ["名称", productName(product.item, product.category)],
        ["城市", product.item.city || ""],
        ["成本价", productCostValue(product.item, product.category) === "" ? "缺成本" : money(productCostValue(product.item, product.category))],
        ["参考售价", productSaleValue(product.item, product.category) === "" ? "-" : money(productSaleValue(product.item, product.category))],
        ["供应商", productSupplierName(product.item) || "缺供应商"],
        ["状态", product.status],
        ["缺失字段", missing.join("、") || "无"],
      ].map(([label, value]) => `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong></div>`).join("")}
    </div>
    <div class="modal-actions">
      <button class="primary-btn" data-sync-mode="formal">同步为正式产品</button>
      <button class="secondary-btn" data-sync-mode="pending">同步为待清洗产品</button>
      <button class="ghost-btn" data-sync-mode="current">仅当前报价使用</button>
      <button class="ghost-btn" data-sync-mode="cancel">取消</button>
    </div>`;
  modal.querySelectorAll("[data-sync-mode]").forEach((btn) => btn.addEventListener("click", () => applyQuoteProductSync(modal, data, product, btn.dataset.syncMode)));
  modal.classList.remove("hidden");
}

function ensureQuoteSyncModal() {
  let modal = $("#quoteSyncModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "quoteSyncModal";
  modal.className = "modal-backdrop hidden";
  modal.innerHTML = `<div class="modal-card"><div class="modal-head"><div><h3>同步报价项到产品库</h3><p>正式同步前请确认字段，内部成本默认不会客户可见。</p></div><button class="icon-btn" data-sync-close aria-label="关闭"><i data-lucide="x"></i></button></div><div class="modal-body" data-sync-body></div></div>`;
  document.body.appendChild(modal);
  modal.querySelector("[data-sync-close]").addEventListener("click", () => modal.classList.add("hidden"));
  return modal;
}

function quoteRowToProduct({ service, row, day }) {
  const categoryMap = { vehicle: "用车", guide: "导游", ticket: "门票", hotel: "酒店", meal: "餐厅", traffic: "大交通", other: "其他" };
  const category = categoryMap[service] || "其他";
  let item = { city: row.city || day.city || "", supplierName: row.supplierName || IMPORTED_PENDING_SUPPLIER, source: "报价台手动同步", updatedAt: new Date().toISOString().slice(0, 10) };
  if (service === "vehicle") item = { ...item, route: row.route || row.legLabel || day.overview || "报价台用车", vehicleType: row.serviceType || "包车", serviceType: row.serviceType || "包车", model: row.model || getDemandSafe().charterVehicleType || "7座车", costPrice: vehicleCost(row), salePrice: sellMargin(vehicleCost(row)) };
  if (service === "guide") item = { ...item, language: getDemandSafe().guideLang || "英语", guideType: "地陪", fullDayCost: row.serviceCost, costPrice: guideCost(row), salePrice: sellMargin(guideCost(row)) };
  if (service === "ticket") {
    const first = row.items?.[0] || {};
    item = { ...item, scenicName: first.name || day.overview || "报价台门票", agencyAdult: first.adultCost, agencyDiscount: first.childCost, costPrice: first.adultCost, adultPrice: first.adultCost, childPrice: first.childCost };
  }
  if (service === "hotel") {
    const first = row.rooms?.[0] || {};
    item = { ...item, hotelName: first.hotelName || `${day.city || ""}参考酒店`, roomType: first.roomType || "房型待定", breakfast: first.breakfast || "", costPrice: first.unitCost, agreementCost: first.unitCost, salePrice: sellMargin(first.unitCost), star: normalizeHotelStar(getDemandSafe().hotelLevel) };
  }
  if (service === "meal") item = { ...item, restaurant: `${day.city || ""}报价台餐厅`, cuisine: (row.meals || []).join("/") || "餐食", costPrice: row.perPersonCost, minSale: sellMargin(row.perPersonCost) };
  if (service === "traffic") item = { ...item, name_cn: row.info || `${day.city || ""}大交通`, adultCost: row.adultCost, childCost: row.childCost, costPrice: row.adultCost };
  if (service === "other") item = { ...item, name: row.sourceName || "报价台其他项目", costPrice: otherCost(row), salePrice: sellMargin(otherCost(row)) };
  item.status = productStatus(item, category);
  return { category, item, status: item.status };
}

function productMissingFields(product, category) {
  return [
    !productName(product.item, category) && "产品名称",
    !product.item.city && "城市",
    productCostValue(product.item, category) === "" && "成本价",
    !productSupplierName(product.item) && "供应商",
  ].filter(Boolean);
}

function applyQuoteProductSync(modal, rowData, product, mode) {
  if (mode === "cancel") return modal.classList.add("hidden");
  if (mode === "current") {
    rowData.row.currentQuoteOnly = true;
    modal.classList.add("hidden");
    renderQuoteTable();
    return;
  }
  product.item.status = mode === "pending" ? "待清洗" : (productMissingFields(product, product.category).length ? "待清洗" : "可报价");
  productCatalogItems(product.category).unshift(product.item);
  rowData.row.syncedProduct = { category: product.category, name: productName(product.item, product.category), mode, syncedAt: new Date().toISOString() };
  rowData.row.source = mergeSources(rowData.row.source || "", `已同步产品库/${product.item.status}`);
  refreshQuoteResources();
  saveLocalProductState();
  modal.classList.add("hidden");
  renderResourceLibrary();
  renderQuoteTable();
  renderSummary();
}

function rematchQuoteRow(token) {
  const { service, index } = parseQuoteRowToken(token);
  buildQuote({ forceRematch: true });
  state.activeService = service;
  renderQuoteTabs();
  renderQuoteTable();
  setAgentPending("message", { title: "已重新匹配产品库", body: `已对第 ${index + 1} 行所在服务项重新匹配产品资源，并刷新报价汇总。` });
}

function markQuoteRowCurrentOnly(token) {
  const { row } = quoteRowByToken(token);
  if (!row) return;
  row.currentQuoteOnly = true;
  row.source = mergeSources(row.source || "", "仅当前报价使用");
  renderQuoteTable();
}

function markQuoteRowPendingClean(token) {
  const { row } = quoteRowByToken(token);
  if (!row) return;
  row.pendingClean = true;
  row.sourceType = "待清洗";
  row.source = mergeSources(row.source || "", "待清洗");
  renderQuoteTable();
}

function openMissingCostQuickFill() {
  const details = missingCostDetails();
  if (!details.length) {
    alert("当前没有待补成本项。");
    return;
  }
  const value = window.prompt(`发现 ${details.length} 个待补成本项。输入一个成本价，将补到当前服务项第一条缺成本记录：`, "0");
  if (value === null) return;
  fillFirstMissingCost(optionalNumber(value));
  renderQuoteTable();
  renderSummary();
}

function fillFirstMissingCost(value) {
  const quote = activeQuote().data;
  const service = state.activeService;
  const rows = quote[service] || [];
  for (const row of rows) {
    if (service === "vehicle" && (row.missingCost || row.charterCost === "")) { row.charterCost = value; markManualRow(row); return; }
    if (service === "guide" && (row.missingCost || row.serviceCost === "")) { row.serviceCost = value; markManualRow(row); return; }
    if (service === "meal" && (row.missingCost || row.perPersonCost === "")) { row.perPersonCost = value; markManualRow(row); return; }
    if (service === "traffic" && (row.adultCost === "" || row.missingCost)) { row.adultCost = value; markManualRow(row); return; }
    if (service === "ticket") {
      const item = row.items?.find((x) => x.missingCost || x.adultCost === "");
      if (item) { item.adultCost = value; markManualRow(item); return; }
    }
    if (service === "hotel") {
      const room = row.rooms?.find((x) => x.missingCost || x.unitCost === "");
      if (room) { room.unitCost = value; markManualRow(room); return; }
    }
  }
}

function table(headers, rows, service) {
  return `<div class="quote-table-wrap"><table class="quote-table ${service}-table">${colGroup(service)}<thead><tr>${headers.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows || `<tr><td colspan="${headers.length}">暂无数据</td></tr>`}</tbody></table></div>`;
}

function colGroup(service) {
  const widths = {
    vehicle: [9, 8, 27, 14, 16, 12, 14],
    guide: [9, 8, 25, 14, 12, 12, 10, 10],
    ticket: [9, 8, 26, 38, 9, 10],
    hotel: [9, 8, 26, 39, 9, 9],
    meal: [9, 8, 28, 22, 13, 10, 10],
    traffic: [8, 7, 23, 11, 20, 10, 10, 6, 5],
    other: [8, 7, 22, 8, 8, 8, 8, 14, 8, 9],
  }[service] || [];
  return widths.length ? `<colgroup>${widths.map((width) => `<col style="width:${width}%">`).join("")}</colgroup>` : "";
}

function resourceCandidateLabel(resource) {
  const parts = [
    resource.name,
    resource.ticketType || resource.model || resource.roomType || resource.vehicleType || "",
    resource.cost === "" ? "待补成本" : money(resource.cost),
  ].filter(Boolean);
  return parts.join(" / ");
}

function quoteSourceInput(sourceOrRow, candidates = [], reason = "") {
  if (sourceOrRow && typeof sourceOrRow === "object" && !Array.isArray(sourceOrRow)) {
    return {
      source: sourceOrRow.source || sourceOrRow.routeProductSource || "",
      candidates: sourceOrRow.candidates || candidates || [],
      reason: sourceOrRow.matchReason || reason || "",
      matchStatus: sourceOrRow.matchStatus || "",
      sourceType: sourceOrRow.sourceType || sourceOrRow.costSource || "",
      costSource: sourceOrRow.costSource || sourceOrRow.sourceType || "",
      sourceName: sourceOrRow.sourceName || sourceOrRow.productName || sourceOrRow.name || sourceOrRow.hotelName || "",
      supplierName: sourceOrRow.supplierName || "",
      missingCost: Boolean(sourceOrRow.missingCost),
    };
  }
  return { source: sourceOrRow || "", candidates: candidates || [], reason: reason || "" };
}

function fallbackQuoteSourceSummary(input = {}) {
  const source = String(input.source || "").replace(/待补价|待询价|大交通待录入/g, "待补成本");
  const reason = input.reason || "";
  const candidates = input.candidates || [];
  const combined = `${source} ${reason}`;
  const status = input.matchStatus
    || (/未匹配|不匹配|未找到|车型缺失/.test(combined) ? "unmatched" : /待确认|候选|待选择/.test(combined) ? "need_confirm" : /待补成本|缺成本/.test(combined) || input.missingCost ? "need_price" : source ? "matched" : "");
  const label = status === "unmatched" ? "未匹配"
    : status === "need_confirm" ? (candidates.length ? `待确认 · ${candidates.length} 个候选` : "待确认")
    : status === "need_price" ? "待补成本"
    : /产品库|Excel|云端|系统底库/.test(`${input.sourceType || ""} ${source}`) ? "产品库成本"
    : /供应商/.test(input.sourceType || "") ? "供应商成本"
    : source ? "产品库成本"
    : "";
  const details = [
    source ? `来源：${source}` : "",
    reason ? `原因：${reason}` : "",
    candidates.length ? `候选：${candidates.slice(0, 6).map(resourceCandidateLabel).join("；")}${candidates.length > 6 ? `；等 ${candidates.length} 条` : ""}` : "",
  ].filter(Boolean);
  return { label, status, level: status === "unmatched" ? "danger" : status === "matched" ? "ok" : "warn", detail: details.join("\n"), candidateCount: candidates.length };
}

function quoteSourceSummary(sourceOrRow, candidates = [], reason = "") {
  const input = quoteSourceInput(sourceOrRow, candidates, reason);
  const displayApi = globalThis.YouyixingQuoteDisplay || globalThis.YouyixingQuoteDomain || {};
  return (displayApi.summarizeQuoteSource || fallbackQuoteSourceSummary)(input);
}

function quoteDetailHtml(detail = "") {
  const lines = String(detail || "").split("\n").filter(Boolean);
  if (!lines.length) return "";
  return `<details class="quote-source-detail"><summary>详情</summary>${lines.map((line) => `<div>${escapeHtml(line)}</div>`).join("")}</details>`;
}

function sourceNote(sourceOrRow, candidates = [], reason = "") {
  const meta = quoteSourceSummary(sourceOrRow, candidates, reason);
  if (!meta?.label) return "";
  return `<div class="cost-source cost-source-${escapeHtml(meta.level || "info")}"><span class="quote-source-chip ${escapeHtml(meta.level || "info")}">${escapeHtml(meta.label)}</span>${quoteDetailHtml(meta.detail)}</div>`;
}

function compactInfoNote(label, detail, level = "info") {
  if (!detail) return "";
  return `<div class="cost-source cost-source-${escapeHtml(level)}"><span class="quote-source-chip ${escapeHtml(level)}">${escapeHtml(label)}</span>${quoteDetailHtml(String(detail))}</div>`;
}

function quoteDiagnosticCostValue(service, row = {}) {
  const fields = {
    vehicle: ["charterCost", "unitCost", "totalCost"],
    guide: ["serviceCost", "unitCost", "totalCost"],
    ticket: ["adultCost", "unitCost", "totalCost"],
    hotel: ["unitCost", "totalCost"],
    meal: ["perPersonCost", "unitCost", "totalCost"],
    traffic: ["adultCost", "unitCost", "totalCost"],
    other: ["routeProductUnitCost", "unitCost", "totalCost"],
  }[service] || ["unitCost", "cost", "totalCost"];
  for (const field of fields) {
    if (row[field] !== "" && row[field] != null) return row[field];
  }
  return "";
}

function quoteDiagnosticProductName(service, row = {}, context = {}) {
  if (service === "vehicle") return row.productName || row.legLabel || row.route || row.serviceType || "用车";
  if (service === "guide") return row.sourceName || `${context.city || ""}导游`;
  if (service === "ticket") return row.name || row.sourceName || "门票";
  if (service === "hotel") return row.hotelName || row.sourceName || "酒店";
  if (service === "meal") return row.sourceName || (row.meals || []).join("、") || "餐";
  if (service === "traffic") return row.sourceName || row.info || row.type || "大交通";
  if (service === "other") return row.sourceName || "其他费用";
  return row.sourceName || row.name || serviceLabels[service] || "服务";
}

function quoteDiagnosticStatusText(status) {
  return {
    matched: "已匹配",
    need_confirm: "待确认",
    need_price: "待补成本",
    unmatched: "未匹配",
  }[status] || "待确认";
}

function shortDiagnosticText(value, limit = 92) {
  const textValue = String(value || "").replace(/\s+/g, " ").trim();
  return textValue.length > limit ? `${textValue.slice(0, limit)}...` : textValue;
}

function pushQuoteDiagnosticRow(rows, service, row = {}, index = 0, context = {}) {
  const itineraryDay = state.itinerary[context.dayIndex ?? index] || {};
  const city = row.city || context.city || itineraryDay.city || "";
  const sourceMeta = quoteSourceSummary(row);
  const unitCost = quoteDiagnosticCostValue(service, row);
  const missingCost = Boolean(row.missingCost) || unitCost === "";
  const status = row.matchStatus || (missingCost ? "need_price" : sourceMeta?.status || "matched");
  rows.push({
    service,
    serviceName: serviceLabels[service] || service,
    city,
    productName: quoteDiagnosticProductName(service, row, { city }),
    unitCost,
    missingCost,
    matchStatus: status,
    matchReason: row.matchReason || "",
    source: row.source || row.routeProductSource || "",
    sourceType: row.sourceType || row.costSource || "",
    sourceName: row.sourceName || "",
    supplierName: row.supplierName || "",
    sourceProductId: row.sourceProductId || "",
    sourceResourceId: row.sourceResourceId || "",
    serviceDetailId: row.serviceDetailId || "",
    candidateCount: (row.candidates || []).length,
  });
}

function buildQuoteDiagnosticsSnapshot(serviceFilter = "") {
  const quote = activeQuote();
  const data = quote?.data || {};
  const rows = [];
  const services = serviceFilter ? [serviceFilter] : Object.keys(data);
  services.forEach((service) => {
    (data[service] || []).forEach((row, index) => {
      if (service === "ticket") {
        (row.items || []).forEach((item) => pushQuoteDiagnosticRow(rows, service, item, index, { dayIndex: index }));
        return;
      }
      if (service === "hotel") {
        (row.rooms || []).forEach((room) => pushQuoteDiagnosticRow(rows, service, room, index, { dayIndex: index }));
        return;
      }
      pushQuoteDiagnosticRow(rows, service, row, index, { dayIndex: row.dayIndex ?? index });
    });
  });
  const counts = rows.reduce((acc, row) => {
    const key = row.missingCost && row.matchStatus === "matched" ? "need_price" : row.matchStatus || "need_confirm";
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, { matched: 0, need_confirm: 0, need_price: 0, unmatched: 0 });
  const snapshot = { generatedAt: new Date().toISOString(), rows, counts };
  try {
    localStorage.setItem("youyixing_quote_diagnostics_latest", JSON.stringify(snapshot));
  } catch (error) {
    console.warn("quote diagnostics not persisted", error);
  }
  return snapshot;
}

function renderQuoteDiagnosticsPanel(service) {
  const snapshot = buildQuoteDiagnosticsSnapshot(service);
  const rows = snapshot.rows || [];
  if (!rows.length) return "";
  const counts = snapshot.counts || {};
  const issueRows = rows.filter((row) => row.matchStatus !== "matched" || row.missingCost);
  const displayRows = (issueRows.length ? issueRows : rows).slice(0, 12);
  const summary = `${serviceLabels[service] || "报价"}诊断：${counts.matched || 0} 已匹配，${counts.need_confirm || 0} 待确认，${counts.need_price || 0} 待补成本，${counts.unmatched || 0} 未匹配`;
  return `
    <details class="quote-diagnostics-panel">
      <summary>${escapeHtml(summary)}</summary>
      <table class="simple-table quote-diagnostics-table">
        <thead><tr><th>服务</th><th>城市</th><th>项目</th><th>状态</th><th>成本</th><th>来源</th><th>说明</th></tr></thead>
        <tbody>
          ${displayRows.map((row) => `
            <tr>
              <td>${escapeHtml(row.serviceName)}</td>
              <td>${escapeHtml(row.city || "-")}</td>
              <td>${escapeHtml(row.productName || "-")}</td>
              <td><span class="quote-source-chip ${row.matchStatus === "matched" && !row.missingCost ? "ok" : row.matchStatus === "unmatched" ? "danger" : "warn"}">${escapeHtml(row.missingCost ? "待补成本" : quoteDiagnosticStatusText(row.matchStatus))}</span></td>
              <td>${row.unitCost === "" ? "待补成本" : money(row.unitCost)}</td>
              <td>${escapeHtml(row.sourceName || row.supplierName || row.sourceType || "-")}</td>
              <td title="${escapeHtml(row.source || row.matchReason || "")}">${escapeHtml(shortDiagnosticText(row.matchReason || row.source || (row.candidateCount ? `${row.candidateCount} 个候选` : "")))}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </details>
  `;
}

function bindQuoteInputs() {
  $$("[data-q]").forEach((input) => input.addEventListener("input", () => {
    const [service, index, field] = input.dataset.q.split(":");
    const row = activeQuote().data[service][Number(index)];
    row[field] = input.type === "number" ? valueOrBlank(input.value) : input.value;
    markManualField(row, field, input.value);
    renderSummary();
    renderQuoteTabs();
  }));
  $$("[data-q]").forEach((input) => input.addEventListener("change", renderQuoteTable));
  $$("[data-ticket]").forEach((input) => input.addEventListener("input", () => {
    const [dayIndex, subIndex, field] = input.dataset.ticket.split(":");
    const item = activeQuote().data.ticket[Number(dayIndex)].items[Number(subIndex)];
    item[field] = input.type === "number" ? valueOrBlank(input.value) : input.value;
    markManualField(item, field, input.value);
    renderSummary();
    renderQuoteTabs();
  }));
  $$("[data-ticket]").forEach((input) => input.addEventListener("change", () => {
    const [dayIndex, subIndex, field] = input.dataset.ticket.split(":");
    const item = activeQuote().data.ticket[Number(dayIndex)].items[Number(subIndex)];
    if (field === "name") {
      const standardName = standardizeEnglishAttractions(input.value);
      if (standardName !== input.value) {
        input.value = standardName;
        item.name = standardName;
      }
      const lookup = lookupTicketCost(standardName, state.itinerary[Number(dayIndex)]?.city);
      item.adultCost = lookup.adultCost;
      item.childCost = lookup.childCost;
      item.source = lookup.source;
      item.missingCost = lookup.adultCost === "" || (getDemand().children && lookup.childCost === "");
      Object.assign(item, traceFields(lookup, lookup.sourceType || "产品库"));
    }
    renderQuoteTable();
    renderSummary();
    renderQuoteTabs();
  }));
  $$("[data-add-ticket]").forEach((btn) => btn.addEventListener("click", () => {
    activeQuote().data.ticket[Number(btn.dataset.addTicket)].items.push({ name: "", adultCost: "", childCost: "" });
    renderQuoteTable();
  }));
  $$("[data-remove-ticket]").forEach((btn) => btn.addEventListener("click", () => {
    const [dayIndex, subIndex] = btn.dataset.removeTicket.split(":").map(Number);
    activeQuote().data.ticket[dayIndex].items.splice(subIndex, 1);
    renderQuoteTable();
    renderSummary();
  }));
  $$("[data-room]").forEach((input) => input.addEventListener("input", () => {
    const [dayIndex, subIndex, field] = input.dataset.room.split(":");
    const room = activeQuote().data.hotel[Number(dayIndex)].rooms[Number(subIndex)];
    room[field] = input.type === "number" ? valueOrBlank(input.value) : input.value;
    markManualField(room, field, input.value);
    renderSummary();
    renderQuoteTabs();
  }));
  $$("[data-room]").forEach((input) => input.addEventListener("change", renderQuoteTable));
  $$("[data-add-room]").forEach((btn) => btn.addEventListener("click", () => {
    const d = getDemand();
    const day = state.itinerary[Number(btn.dataset.addRoom)];
    activeQuote().data.hotel[Number(btn.dataset.addRoom)].rooms.push({
      hotelName: `${day.city}${d.hotelLevel}参考酒店`,
      breakfast: d.hotelBreakfast,
      roomType: d.roomTypes[0]?.type || "双床房",
      rooms: d.roomTypes[0]?.rooms || d.rooms,
      unitCost: lookupResourceCost("hotel", day.city, d.hotelLevel, resources.hotel, d.hotelLevel).cost,
      source: lookupResourceCost("hotel", day.city, d.hotelLevel, resources.hotel, d.hotelLevel).source,
    });
    renderQuoteTable();
    renderSummary();
  }));
  $$("[data-remove-room]").forEach((btn) => btn.addEventListener("click", () => {
    const [dayIndex, subIndex] = btn.dataset.removeRoom.split(":").map(Number);
    activeQuote().data.hotel[dayIndex].rooms.splice(subIndex, 1);
    renderQuoteTable();
    renderSummary();
  }));
  $$("[data-meal]").forEach((input) => input.addEventListener("input", () => {
    const [index, meal] = input.dataset.meal.split(":");
    const row = activeQuote().data.meal[Number(index)];
    row.meals = row.meals.filter((x) => x !== meal);
    if (input.checked) row.meals.push(meal);
    row.perPersonCost = row.meals.reduce((sum, x) => sum + number(resources.meals[x]), 0);
    markManualField(row, "meals", row.meals.join("、"));
    renderQuoteTable();
    renderSummary();
    renderQuoteTabs();
  }));
}

function markManualField(row, field, value) {
  if (!row) return;
  row.manualFields = { ...(row.manualFields || {}), [field]: true };
  if (value !== "" && value != null) markManualRow(row);
  row.lastManualEdit = { field, value, editedAt: new Date().toISOString() };
  renderXiaoyiContext();
}

function activeQuote() {
  return state.quoteVersions[state.activeQuote];
}

function newQuoteVersion() {
  const current = JSON.parse(JSON.stringify(activeQuote().data));
  state.quoteVersions.push({ name: `报价 V${state.quoteVersions.length + 1}`, status: "草稿", data: current });
  state.activeQuote = state.quoteVersions.length - 1;
  renderQuoteVersionSelect();
  renderQuoteTable();
  renderSummary();
  renderArchive();
}

function handleSaveVersion() {
  activeQuote().status = "已保存";
  saveQuoteVersionMeta(state.proposalConfirmed);
  updateCurrentProject();
  saveCurrentProjectSnapshot();
  renderArchive();
  $("#projectStatus").textContent = "报价已保存";
  $("#projectStatus").className = "status ok";
  alert("草稿已保存。");
}

function submitQuote() {
  if (!activeQuote()?.data?.vehicle?.length && state.routeConfirmed) buildQuote({ auto: true });
  saveQuoteVersionMeta(state.proposalConfirmed);
  activeQuote().status = "已提交";
  const missing = countMissingCosts();
  if (missing) {
    const ok = window.confirm(`当前仍有 ${missing} 项缺少成本，报价总成本可能不完整。是否仍提交报价？`);
    if (!ok) return;
  }
  updateCurrentProject("价格已报但未成交");
  saveCurrentProjectSnapshot();
  renderArchive();
  renderProposalGuard();
  showProjectDashboard();
  alert("报价已提交，项目已保存并返回报价项目列表。");
}

function renderQuoteVersionSelect() {
  $("#quoteVersion").innerHTML = state.quoteVersions.map((version, index) => `<option value="${index}" ${index === state.activeQuote ? "selected" : ""}>${version.name}</option>`).join("");
}

function renderRateCard() {
  const code = $("#currency").value;
  const rate = dailyRates[code];
  $("#rateCard").textContent = code === "CNY" ? "今日汇率：人民币 1.00" : `今日汇率：1 ${rate.label} = ${rate.rate} 人民币`;
}

function renderSummary() {
  const quote = activeQuote();
  if (!quote || !quote.data || !state.itinerary.length) {
    $("#summaryPanel").className = "panel empty";
    $("#summaryPanel").textContent = "行程生成后会自动汇总成本价和参考售价。";
    renderWorkbenchOverview();
    renderQuoteFlowLine();
    return;
  }
  const totals = calcTotals();
  const d = getDemand();
  const missing = countMissingCosts();
  const needConfirm = countQuoteRowsByMatchStatus("need_confirm");
  const missingDetails = missingCostDetails();
  const trafficMargin = number($("#trafficFeeRate")?.value || $("#ruleTrafficMargin")?.value) || 6;
  const trafficMinProfit = number($("#ruleTrafficMinProfit")?.value) || 30;
  const grossRate = totals.sell ? Math.round(((totals.sell - totals.cost) / totals.sell) * 10000) / 100 : 0;
  if ($("#grossProfitAmount")) $("#grossProfitAmount").value = money(totals.grossProfit);
  if ($("#trafficFeeRate")) $("#trafficFeeRate").value = trafficMargin;
  if ($("#trafficFeeAmount")) $("#trafficFeeAmount").value = money(totals.trafficFee);
  const rows = serviceEnabledList().map((service) => {
    const cost = serviceCost(service);
    const sell = serviceSell(service);
    return `<tr><td>${serviceLabels[service]}</td><td>${money(cost)}</td><td>${money(sell)}</td><td>${money(sell - cost)}</td></tr>`;
  }).join("");
  $("#summaryPanel").className = "panel";
  $("#summaryPanel").innerHTML = `
    <div class="summary-cards">
      <div class="summary-card"><span>成本总计</span><strong>${money(totals.cost)}</strong></div>
      <div class="summary-card"><span>参考售价总计</span><strong>${money(totals.sell)}</strong></div>
      <div class="summary-card"><span>预计毛利</span><strong>${money(totals.sell - totals.cost)}</strong></div>
      <div class="summary-card"><span>毛利率</span><strong class="${grossRate < 8 ? "danger-text" : "ok-text"}">${grossRate}%</strong></div>
      <div class="summary-card"><span>大交通成本</span><strong>${money(totals.trafficCost)}</strong></div>
      <div class="summary-card"><span>大交通服务费</span><strong>${money(totals.trafficFee)}</strong></div>
      <div class="summary-card"><span>最终报价</span><strong>${money(totals.sell)}</strong></div>
      <div class="summary-card"><span>成人均价</span><strong>${money(totals.adultAvg)}</strong></div>
      <div class="summary-card"><span>待补成本项数量</span><strong class="${missing ? "danger-text" : "ok-text"}">${missing}</strong></div>
      <div class="summary-card"><span>待确认资源数量</span><strong class="${needConfirm ? "danger-text" : "ok-text"}">${needConfirm}</strong></div>
    </div>
    ${missing ? `<div class="notice danger">当前仍有 ${missing} 项缺少成本，报价总成本可能不完整。</div>` : ""}
    <div class="summary-grid">
      <div><table class="simple-table"><thead><tr><th>服务项</th><th>成本价</th><th>参考售价</th><th>毛利</th></tr></thead><tbody>${rows}</tbody></table></div>
      <div class="check-list">
        <div><strong>缺失成本</strong><br><span>${missing} 项需要补价</span>${missingDetails.length ? `<ul class="missing-list">${missingDetails.slice(0, 8).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : `<p>暂无缺失成本。</p>`}</div>
        <div><strong>风险提示</strong><br><span>${riskSummaryText(grossRate, missingDetails, trafficMargin)}</span></div>
        <div><strong>大交通服务费</strong><br><span>按 ${trafficMargin}% 计算，最低 ${trafficMinProfit} 元；费率可在报价版本区修改。</span></div>
      </div>
    </div>
  `;
  renderWorkbenchOverview();
  renderQuoteFlowLine();
  renderXiaoyiContext();
}

function countQuoteRowsByMatchStatus(status) {
  const quote = activeQuote()?.data || {};
  const rows = [];
  Object.values(quote).forEach((serviceRows) => {
    (serviceRows || []).forEach((row) => {
      rows.push(row);
      (row.items || []).forEach((item) => rows.push(item));
      (row.rooms || []).forEach((room) => rows.push(room));
    });
  });
  return rows.filter((row) => row.matchStatus === status).length;
}

function calcTotals() {
  const d = getDemand();
  const cost = serviceEnabledList().reduce((sum, service) => sum + serviceCost(service), 0);
  const sell = serviceEnabledList().reduce((sum, service) => sum + serviceSell(service), 0);
  const trafficCostTotal = serviceEnabledList().includes("traffic") ? serviceCost("traffic") : 0;
  const trafficSellTotal = serviceEnabledList().includes("traffic") ? serviceSell("traffic") : 0;
  const childRatio = d.children ? 0.65 : 1;
  const weightedPeople = d.adults + d.children * childRatio;
  const basePeople = weightedPeople > 0 ? weightedPeople : 1;
  return {
    cost,
    sell,
    grossProfit: sell - cost,
    trafficCost: trafficCostTotal,
    trafficFee: Math.max(trafficSellTotal - trafficCostTotal, 0),
    adultAvg: d.adults > 0 ? sell / basePeople : 0,
    childAvg: d.children ? (sell / basePeople) * childRatio : 0,
  };
}

function serviceCost(service) {
  const data = activeQuote().data[service] || [];
  const map = { vehicle: vehicleCost, guide: guideCost, ticket: ticketCost, hotel: hotelCost, meal: mealCost, traffic: trafficCost, other: otherCost };
  return data.reduce((sum, row) => sum + map[service](row), 0);
}

function serviceSell(service) {
  const cost = serviceCost(service);
  return service === "traffic" ? sellTraffic(cost) : sellMargin(cost);
}

function vehicleCost(row) { return number(row.charterCost) + number(row.driverCost); }
function guideCost(row) { return number(row.serviceCost) + number(row.ticketCost) + number(row.hotelCost); }
function ticketCost(row) {
  const d = getDemand();
  return row.items.reduce((sum, item) => sum + number(item.adultCost) * d.adults + number(item.childCost) * d.children, 0);
}
function hotelCost(row) { return row.rooms.reduce((sum, room) => sum + number(room.rooms) * number(room.unitCost), 0); }
function mealCost(row) { return number(row.perPersonCost) * getDemand().people; }
function trafficCost(row) { const d = getDemand(); return number(row.adultCost) * d.adults + number(row.childCost) * d.children; }
function otherCost(row) {
  const d = getDemand();
  return (number(row.insurance) + number(row.headset) + number(row.water) + number(row.routeProductUnitCost)) * d.people + number(row.gift) * d.people;
}

function sellMargin(cost) {
  const margin = number($("#grossMargin").value) / 100;
  return margin >= 1 ? cost : cost / (1 - margin);
}

function sellTraffic(cost) {
  if (!cost) return 0;
  const rate = number($("#trafficFeeRate")?.value || $("#ruleTrafficMargin")?.value || 6) / 100;
  const minimum = number($("#ruleTrafficMinProfit")?.value || 30);
  return cost * rate < minimum ? cost + minimum : cost * (1 + rate);
}

function riskSummaryText(grossRate, missingDetails, trafficMargin) {
  const risks = [];
  if (missingDetails.length) risks.push(`${missingDetails.length} 处成本待补录`);
  if (trafficMargin === 6 && serviceEnabledList().includes("traffic")) risks.push("大交通服务费仍为默认 6%");
  if (grossRate < 8) risks.push("综合毛利率低于 8%");
  if ($("#outputLang")?.value === "en" && state.translation.residues.length) risks.push(`英文提案有 ${state.translation.residues.length} 处中文残留`);
  return risks.length ? risks.join("；") : "当前未发现明显风险。";
}

function countMissingCosts(onlyService = "") {
  const quote = activeQuote().data;
  let count = 0;
  const checkedServices = onlyService ? [onlyService] : serviceEnabledList();
  const include = (service) => checkedServices.includes(service);
  if (include("vehicle")) quote.vehicle.forEach((x) => { if (x.missingCost || (x.charterCost === "" && x.source !== "未包含")) count += 1; });
  if (include("guide")) quote.guide.forEach((x) => { if (x.missingCost || x.serviceCost === "") count += 1; });
  if (include("ticket")) quote.ticket.forEach((x) => x.items.forEach((item) => { if (item.missingCost || item.adultCost === "" || (getDemand().children && item.childCost === "")) count += 1; }));
  if (include("hotel")) quote.hotel.forEach((x) => x.rooms.forEach((room) => { if (room.missingCost || room.unitCost === "" || number(room.rooms) === 0) count += 1; }));
  if (include("meal")) quote.meal.forEach((x) => { if (x.missingCost || (x.meals.length && x.perPersonCost === "")) count += 1; });
  if (include("traffic")) quote.traffic.forEach((x) => { if (x.type && (x.adultCost === "" || number(x.adultCost) === 0 || (getDemand().children && (x.childCost === "" || number(x.childCost) === 0)))) count += 1; });
  if (include("other")) quote.other.forEach((x) => { if (x.missingCost) count += 1; });
  return count;
}

function missingCostDetails() {
  const quote = activeQuote().data;
  const d = getDemand();
  const details = [];
  const dayLabel = (index) => {
    const day = state.itinerary[index] || {};
    return `${day.date || `第${index + 1}天`} ${day.city || ""}`.trim();
  };
  if (d.services.vehicle) quote.vehicle.forEach((row, index) => {
    if (row.missingCost || (row.charterCost === "" && row.source !== "未包含")) details.push(`${dayLabel(row.dayIndex ?? index)}：${row.legLabel || row.serviceType || "用车"}成本待选择或待补录成本`);
  });
  if (d.services.guide) quote.guide.forEach((row, index) => {
    if (row.missingCost || row.serviceCost === "") details.push(`${dayLabel(index)}：导游服务费缺失`);
  });
  if (d.services.ticket) quote.ticket.forEach((row, index) => row.items.forEach((item) => {
    if (item.sourceType === "成本缺失" || item.adultCost === "") details.push(`${dayLabel(index)}：门票「${item.name || "未命名"}」成人成本缺失`);
    if (d.children && (item.sourceType === "成本缺失" || item.childCost === "")) details.push(`${dayLabel(index)}：门票「${item.name || "未命名"}」儿童成本缺失`);
  }));
  if (d.services.hotel) quote.hotel.forEach((row, index) => row.rooms.forEach((room) => {
    if (number(room.rooms) === 0) details.push(`${dayLabel(index)}：酒店「${room.roomType || "房型"}」房间数为0`);
    if (room.missingCost || room.unitCost === "") details.push(`${dayLabel(index)}：酒店「${room.hotelName || room.roomType || "房型"}」单房成本缺失`);
  }));
  if (d.services.meal) quote.meal.forEach((row, index) => {
    if (row.missingCost || (row.meals.length && row.perPersonCost === "")) details.push(`${dayLabel(index)}：餐厅成本缺失，需运营补成本`);
  });
  if (d.services.traffic) quote.traffic.forEach((row, index) => {
    if (row.type && (row.adultCost === "" || number(row.adultCost) === 0)) details.push(`${dayLabel(index)}：大交通成人成本缺失或为0`);
    if (row.type && d.children && (row.childCost === "" || number(row.childCost) === 0)) details.push(`${dayLabel(index)}：大交通儿童成本缺失或为0`);
  });
  if (d.services.other) quote.other.forEach((row, index) => {
    if (row.missingCost) details.push(`${dayLabel(index)}：线路产品「${row.sourceName || "未命名"}」人数超出成本档位，待询价`);
  });
  return details;
}

async function handleBuildProposal() {
  if (!state.routeConfirmed) {
    alert("请先确认线路并刷新报价，再生成客户方案。");
    showWorkbenchSection("q-itinerary");
    return;
  }
  const lang = $("#outputLang").value;
  const source = createChineseProposalSource();
  if (!source) return;
  if (lang === "en") {
    await generateEnglishProposalVersion({ source });
    updateCurrentProject("价格已报但未成交");
    return;
  }
  state.proposalEditing = false;
  state.proposalConfirmed = false;
  if (!state.itinerary.length) handleGenerateItinerary();
  if (!activeQuote().data.vehicle.length) buildQuote();
  const t = i18n[lang] || i18n.zh;
  const d = getDemand();
  const totals = calcTotals();
  const cities = unique(state.itinerary.map((day) => day.city)).map((city) => translate(city, lang));
  const days = state.itinerary.map((day) => localizeDay(day, lang));
  const showTotal = $("#priceTotal").checked || (!$("#priceAverage").checked && !$("#priceItemized").checked);
  const showAverage = $("#priceAverage").checked;
  const showItemized = $("#priceItemized").checked;
  $("#proposal").classList.toggle("watermarked", $("#proposalWatermark").checked);
  applyProposalCoverImage();
  $("#proposalKicker").textContent = t.kicker;
  $("#proposalTitle").textContent = t.title(d.serviceDays, cities);
  $("#proposalMeta").textContent = `${d.startDate || t.tbd} · ${d.people} ${t.guests}`;
  $("#proposalContent").innerHTML = `
    <div class="proposal-grid">
      <div>
        <div class="proposal-block">
          <h4>${t.itinerary}</h4>
          ${days.map((day, index) => `<div class="proposal-day"><strong>${t.day} ${index + 1}</strong><div><b>${day.date} · ${day.city} · ${day.overview}</b><p>${day.detail}</p></div></div>`).join("")}
        </div>
        ${costPolicyHtml(lang)}
      </div>
      <aside>
        <div class="price-box">
          <span>${t.total}</span>
          ${showTotal ? `<strong>${money(totals.sell)}</strong>` : ""}
          ${showAverage ? `<span>${t.adultAvg}: ${money(totals.adultAvg)}</span>` : ""}
          ${showAverage && d.children ? `<span>${t.childAvg}: ${money(totals.childAvg)}</span>` : ""}
        </div>
        ${showItemized ? itemizedPriceHtml(lang) : ""}
        <div class="proposal-block"><h4>${t.notesTitle}</h4><p>${t.notes}</p></div>
        ${contactHtml(lang)}
      </aside>
    </div>
  `;
  $("#proposalContent").contentEditable = "false";
  $("#proposal").classList.remove("editing");
  const editLabel = $("#editProposal span");
  if (editLabel) editLabel.textContent = "编辑方案";
  $("#projectStatus").textContent = "已生成客人方案";
  $("#projectStatus").className = "status ok";
  renderEnglishWarning();
  applyProposalCoverImage();
  renderProposalAssets();
  renderProposalGuard();
  renderWorkbenchOverview();
  updateCurrentProject("价格已报但未成交");
}

function applyProposalCoverImage() {
  const img = $("#proposal .proposal-cover img");
  if (!img) return;
  const asset = state.proposalAssets.find((item) => item.url && item.isCover && item.useInProposal)
    || state.proposalAssets.find((item) => item.url && item.confirmed && item.useInProposal)
    || state.proposalAssets.find((item) => item.url && item.useInProposal);
  if (asset?.url) img.src = asset.url;
}

function rebuildProposalIfNeeded() {
  if (state.proposalEditing) return;
  const content = $("#proposalContent");
  if (!content || !content.innerHTML.trim()) return;
  handleBuildProposal();
}

function toggleProposalEdit() {
  const content = $("#proposalContent");
  if (!content || !content.innerHTML.trim()) {
    handleBuildProposal();
  }
  state.proposalEditing = !state.proposalEditing;
  $("#proposalContent").contentEditable = state.proposalEditing ? "true" : "false";
  $("#proposal").classList.toggle("editing", state.proposalEditing);
  const label = $("#editProposal span");
  if (label) label.textContent = state.proposalEditing ? "完成编辑" : "编辑方案";
  if (state.proposalEditing) {
    invalidateProposalConfirmation();
    $("#projectStatus").textContent = "客人方案可手动编辑";
    $("#projectStatus").className = "status ok";
    $("#proposalContent").focus();
  } else {
    invalidateProposalConfirmation();
    $("#projectStatus").textContent = "客人方案已手动编辑";
    $("#projectStatus").className = "status ok";
  }
}

function selectedProposalText() {
  const content = $("#proposalContent");
  const selection = window.getSelection?.();
  if (selection && selection.rangeCount && content?.contains(selection.anchorNode)) {
    const text = selection.toString().trim();
    if (text) return { text, selected: true };
  }
  const paragraph = content?.querySelector("p") || content;
  return { text: paragraph?.innerText?.trim() || "", selected: false, node: paragraph };
}

function replaceProposalText(before, after, fallbackNode = null) {
  const content = $("#proposalContent");
  if (!content || !before || before === after) return false;
  const selection = window.getSelection?.();
  if (selection && selection.rangeCount && content.contains(selection.anchorNode) && selection.toString().trim() === before) {
    const range = selection.getRangeAt(0);
    range.deleteContents();
    range.insertNode(document.createTextNode(after));
    selection.removeAllRanges();
    invalidateProposalConfirmation();
    checkEnglishChineseResidue();
    return true;
  }
  if (content.innerHTML.includes(escapeHtml(before))) {
    content.innerHTML = content.innerHTML.replace(escapeHtml(before), escapeHtml(after));
  } else if (content.textContent.includes(before)) {
    const walker = document.createTreeWalker(content, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node) {
      if (node.nodeValue.includes(before)) {
        node.nodeValue = node.nodeValue.replace(before, after);
        break;
      }
      node = walker.nextNode();
    }
  } else if (fallbackNode) {
    fallbackNode.textContent = after;
  }
  invalidateProposalConfirmation();
  checkEnglishChineseResidue();
  return true;
}

function polishProposalSection() {
  if (!$("#proposalContent")?.innerHTML.trim()) handleBuildProposal();
  const target = selectedProposalText();
  const polished = polishEnglishText(target.text || "");
  if (!polished) return;
  replaceProposalText(target.text, polished, target.node);
  $("#translationStatus").textContent = "已在英文提案区原地优化当前段落。";
}

async function retranslateProposalSection() {
  if (!$("#proposalContent")?.innerHTML.trim()) await handleBuildProposal();
  const target = selectedProposalText();
  if (!target.text) return;
  if (containsChinese(target.text)) {
    $("#translationStatus").textContent = "正在调用 DeepSeek 重新翻译当前段落...";
    try {
      const translated = await translateResidueSegment({
        snippet: target.text,
        text: target.text,
        location: "当前选中段落",
        fullParagraph: target.text,
      });
      replaceProposalText(target.text, translated, target.node);
      $("#translationStatus").textContent = "已调用 DeepSeek 重新翻译当前段落，并重新检测中文残留。";
    } catch (error) {
      $("#translationStatus").textContent = `DeepSeek 局部翻译失败，请检查 API Key 或稍后重试。${error.message ? `错误：${error.message}` : ""}`;
    }
    return;
  }
  const polished = polishEnglishText(target.text);
  replaceProposalText(target.text, polished, target.node);
  $("#translationStatus").textContent = "当前段落没有中文残留，已做轻量英文格式整理。";
}

function polishEnglishProposal() {
  if (!$("#proposalContent")?.innerHTML.trim()) handleBuildProposal();
  const content = $("#proposalContent");
  content.querySelectorAll("p, b, td, li").forEach((node) => {
    if (!containsChinese(node.textContent)) node.textContent = polishEnglishText(node.textContent);
  });
  state.translation.englishPreview = content.innerHTML;
  invalidateProposalConfirmation();
  checkEnglishChineseResidue();
  $("#translationStatus").textContent = "已润色英文提案，并重新检测中文残留。";
}

function restoreProposalOriginal() {
  if (state.translation.originalProposalHtml && $("#proposalContent")) {
    $("#proposalContent").innerHTML = state.translation.originalProposalHtml;
    invalidateProposalConfirmation();
    checkEnglishChineseResidue();
    $("#translationStatus").textContent = "已恢复为最近一次生成的提案原文。";
  }
}

async function refreshSimpleTranslation() {
  if (!state.routeConfirmed) {
    alert("请先确认线路并刷新报价，再刷新英文版。");
    showWorkbenchSection("q-itinerary");
    return;
  }
  const lang = $("#proposalLanguageQuick")?.value || "en";
  if ($("#outputLang")) $("#outputLang").value = lang;
  if (lang === "zh") {
    await handleBuildProposal();
    checkEnglishChineseResidue();
    const count = state.translation.residues.length;
    $("#translationStatus").textContent = count ? `检测到 ${count} 处中文残留，请编辑后确认。` : "翻译已刷新，未检测到中文残留。";
    return;
  }
  await generateEnglishProposalVersion();
  return;
}

function saveSimpleTranslation() {
  if (!$("#proposalContent")?.innerHTML.trim()) {
    alert("请先生成或刷新译文。");
    return;
  }
  state.translation.englishPreview = $("#proposalContent").innerHTML;
  checkEnglishChineseResidue();
  const count = state.translation.residues.length;
  $("#translationStatus").textContent = count ? `检测到 ${count} 处中文残留，请编辑后确认。` : "译文已保存，未检测到中文残留。";
  invalidateProposalConfirmation();
}

function polishEnglishText(text = "") {
  return String(text || "")
    .replace(/\s+/g, " ")
    .replace(/\bTBD\b/g, "to be confirmed")
    .replace(/\bguests\b/gi, "guests")
    .replace(/subject to final confirmation\.?/gi, "subject to final confirmation.")
    .replace(/This quotation is based on the current itinerary and available resources\.?/gi, "This quotation is based on the current itinerary and available resources.")
    .trim();
}

function includedList(lang) {
  const t = i18n[lang] || i18n.zh;
  return serviceEnabledList().map((service) => t.items[service]).filter(Boolean);
}

function costPolicyHtml(lang) {
  const t = i18n[lang] || i18n.zh;
  const headers = t.costHeaders || i18n.en.costHeaders;
  const rows = costPolicyRows(lang);
  return `<div class="proposal-block">
    <h4>${t.costPolicyTitle || `${t.included} / ${t.excluded}`}</h4>
    <table class="simple-table cost-policy-table">
      <thead><tr>${headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr></thead>
      <tbody>${rows.map((row) => `<tr><td>${escapeHtml(row.item)}</td><td>${escapeHtml(row.included)}</td><td>${escapeHtml(row.excluded)}</td></tr>`).join("")}</tbody>
    </table>
  </div>`;
}

const termTranslations = {
  en: {
    "3星标准型": "3-star standard",
    "4星舒适型": "4-star comfort standard",
    "5星品质型": "5-star premium standard",
    "豪华型": "luxury standard",
    "房型待定": "room type to be confirmed",
    "双床房": "twin room",
    "大床房": "double room",
    "三人间": "triple room",
    "套房": "suite",
    "含双早": "breakfast for two included",
    "含早": "breakfast included",
    "不含早": "breakfast not included",
    "英语": "English",
    "阿拉伯语": "Arabic",
    "法语": "French",
    "西班牙语": "Spanish",
    "德语": "German",
    "早餐": "breakfast",
    "午餐": "lunch",
    "晚餐": "dinner",
    "火车": "train",
    "飞机": "flight",
    "都可以": "train or flight",
    "接送机": "airport transfer",
    "仅接机": "airport pickup",
    "仅送机": "airport drop-off",
    "不含": "not included",
    "需要": "required",
    "不需要": "not required",
    "保险": "travel insurance",
    "耳麦": "headsets",
    "水": "bottled water",
    "伴手礼": "souvenir gifts",
    "参考酒店": "reference hotel",
    "14座车": "14-seat vehicle",
    "7座车": "7-seat vehicle",
    "22座车": "22-seat vehicle",
    "33座车": "33-seat vehicle",
  },
};

function localizeTerm(value, lang) {
  const raw = String(value || "").trim();
  if (!raw || lang === "zh") return raw;
  const dict = termTranslations[lang] || termTranslations.en;
  let result = translate(raw, lang);
  Object.entries(dict).sort((a, b) => b[0].length - a[0].length).forEach(([source, target]) => {
    result = result.replaceAll(source, target);
  });
  return safeLocalized(result, lang, result.replace(/[\u4e00-\u9fa5]+/g, "").trim() || raw);
}

function localizeList(values, lang, emptyText = "") {
  const list = unique(values.map((value) => localizeTerm(value, lang)).filter(Boolean));
  if (!list.length) return emptyText;
  return list.join(lang === "zh" ? "、" : ", ");
}

function roomTextForPolicy(d, lang) {
  const rooms = (d.roomTypes.length ? d.roomTypes : [{ type: "房型待定", rooms: d.rooms }])
    .filter((room) => number(room.rooms) > 0);
  if (!rooms.length) return lang === "zh" ? "房型和间数以需求单为准" : "room type and quantity follow the confirmed request";
  if (lang === "zh") return rooms.map((room) => `${room.type}${room.rooms}间`).join("、");
  return rooms.map((room) => `${room.rooms} ${localizeTerm(room.type, lang)}${number(room.rooms) > 1 ? "s" : ""}`).join(", ");
}

function hotelNamesForPolicy(quote, lang) {
  const names = unique((quote.hotel || []).flatMap((row) => (row.rooms || []).map((room) => room.hotelName).filter(Boolean)));
  return localizeList(names.map((name) => localizeHotelName(name, lang)), lang);
}

function localizeHotelName(name, lang) {
  if (lang === "zh") return name;
  const city = inferCity(name || "");
  const level = ["3星标准型", "4星舒适型", "5星品质型", "豪华型"].find((item) => String(name || "").includes(item));
  if (city && level && String(name || "").includes("参考酒店")) {
    return `${localizeTerm(level, lang)} reference hotel in ${translate(city, lang)}`;
  }
  return localizeTerm(name, lang);
}

function ticketNamesForPolicy(quote, lang) {
  const names = unique((quote.ticket || []).flatMap((row) => (row.items || []).map((item) => item.name).filter(Boolean)));
  return localizeList(names, lang, lang === "zh" ? "报价明细中列明景点" : "attractions listed in the quotation details");
}

function trafficDetailsForPolicy(quote, lang) {
  const rows = (quote.traffic || []).map((row, index) => ({ row, index })).filter(({ row }) => row.type);
  if (!rows.length) return lang === "zh" ? `行程中列明的${getDemand().trafficType}` : `listed ${localizeTerm(getDemand().trafficType, lang)}`;
  return rows.map(({ row, index }) => {
    const current = state.itinerary[index] || {};
    const previous = state.itinerary[index - 1] || {};
    const date = current.date || "";
    const from = previous.city || "出发地";
    const to = current.city || "目的地";
    const info = row.info ? localizeTerm(row.info, lang) : (lang === "zh" ? "车次/航班待定" : "train/flight number to be confirmed");
    if (lang === "zh") return `${date} ${from}至${to}（${row.type}，${info}）`;
    return `${date} ${localizeTerm(from, lang)} to ${localizeTerm(to, lang)} (${localizeTerm(row.type, lang)}, ${info})`;
  }).join(lang === "zh" ? "；" : "; ");
}

function costPolicyRows(lang) {
  const d = getDemand();
  const quote = activeQuote().data || emptyQuoteData();
  const rows = [];
  const vehicleDays = new Set(quote.vehicle.filter((row) => vehicleCost(row) > 0).map((row, index) => row.dayIndex ?? index)).size || state.itinerary.length;
  const guideDays = quote.guide.filter((row) => guideCost(row) > 0).length || state.itinerary.length;
  const hotelNights = Math.max(state.itinerary.length - 1, 0);
  const roomText = roomTextForPolicy(d, lang);
  const hotelNames = hotelNamesForPolicy(quote, lang);
  const ticketNames = ticketNamesForPolicy(quote, lang);
  const mealDays = (quote.meal || []).filter((row) => row.meals.length).length || (d.meals.length ? state.itinerary.length : 0);
  const mealText = d.meals.length ? localizeList(d.meals, lang) : (lang === "zh" ? "行程中列明餐食" : "meals listed in the itinerary");
  const transferText = d.transferNeed && d.transferNeed !== "不含"
    ? (lang === "zh" ? `，含${d.transferNeed}` : `, including ${localizeTerm(d.transferNeed, lang)}`)
    : "";
  const otherText = d.other.length ? localizeList(d.other, lang) : (lang === "zh" ? "报价明细中列明项目" : "items listed in the quotation details");
  const trafficText = trafficDetailsForPolicy(quote, lang);
  if (d.services.hotel) rows.push(costPolicyRow("hotel", lang, {
    zhIncluded: `${hotelNames ? `参考酒店：${hotelNames}；` : ""}${d.hotelLevel}，${hotelNights}晚；${roomText}；${d.hotelBreakfast}；酒店及同等级别以最终确认为准。`,
    zhExcluded: "单房差、酒店押金、迷你吧、洗衣、电话费及其他个人消费不含。",
    enIncluded: `${hotelNames ? `Reference hotels: ${hotelNames}; ` : ""}${localizeTerm(d.hotelLevel, lang)}, ${hotelNights} night(s); ${roomText}; ${localizeTerm(d.hotelBreakfast, lang)}; hotel or similar standard is subject to final confirmation.`,
    enExcluded: "Single supplement, hotel deposit, minibar, laundry, phone calls and other personal expenses are excluded.",
  }));
  if (d.services.vehicle) rows.push(costPolicyRow("vehicle", lang, {
    zhIncluded: `${d.charterNeed === "需要" ? `${d.charterVehicleType}按天包车，${vehicleDays}天` : "按需求配置用车"}${transferText}；含司机服务。`,
    zhExcluded: "服务时长外用车、超时费、临时改线增加的车辆费用不含。",
    enIncluded: `${d.charterNeed === "需要" ? `${localizeTerm(d.charterVehicleType, lang)} charter service for ${vehicleDays} day(s)` : "vehicle arranged as requested"}${transferText}; driver service included.`,
    enExcluded: "Overtime, use beyond service hours and extra cost caused by route changes are excluded.",
  }));
  if (d.services.ticket) rows.push(costPolicyRow("ticket", lang, {
    zhIncluded: `${ticketNames}的首道门票；成人/儿童票价以报价明细为准。`,
    zhExcluded: "景区二次消费、索道、电瓶车、游船、演出、个人消费及未列明票种不含。",
    enIncluded: `First entrance tickets for ${ticketNames}; adult/child prices follow the quotation details.`,
    enExcluded: "Secondary consumption, cable cars, shuttle buses, boats, shows, personal expenses and unlisted ticket types are excluded.",
  }));
  if (d.services.guide) rows.push(costPolicyRow("guide", lang, {
    zhIncluded: `${d.guideLang}导游服务，约${guideDays}天；接送机是否含导游以报价明细为准。`,
    zhExcluded: "超时导游服务、额外语种、导游个人门票或住宿等未列明费用不含。",
    enIncluded: `${localizeTerm(d.guideLang, lang)} guide service for about ${guideDays} day(s); airport/station guide assistance follows quotation details.`,
    enExcluded: "Guide overtime, extra language service, guide tickets/accommodation not listed are excluded.",
  }));
  if (d.services.meal) rows.push(costPolicyRow("meal", lang, {
    zhIncluded: `包含${mealText}，约${mealDays}天涉及餐食；餐标、特色餐或参考餐厅以报价明细为准。`,
    zhExcluded: "未列明餐食、酒水、包间费、临时加菜和个人加点不含。",
    enIncluded: `Includes ${mealText}; about ${mealDays} day(s) with meals. Meal standard, special meals or reference restaurants follow quotation details.`,
    enExcluded: "Unlisted meals, drinks, private room fees, extra dishes and personal orders are excluded.",
  }));
  if (d.services.traffic) rows.push(costPolicyRow("traffic", lang, {
    zhIncluded: `${trafficText}；出行日期、起止站、车次/航班号、舱位或座位等级以出票信息为准。`,
    zhExcluded: "改签退票差价、行李超额、升舱、延误产生的额外费用不含。",
    enIncluded: `${trafficText}; travel date, stations, train/flight number and seat/cabin class are subject to issued tickets.`,
    enExcluded: "Change/refund difference, excess baggage, upgrade and delay-related extra cost are excluded.",
  }));
  if (d.services.other) rows.push(costPolicyRow("other", lang, {
    zhIncluded: `${otherText}等已列明项目。`,
    zhExcluded: "未在报价单、行程单或费用包含中列明的服务不含。",
    enIncluded: `Listed items such as ${otherText}.`,
    enExcluded: "Any service not listed in the quotation, itinerary or inclusions is excluded.",
  }));
  return rows;
}

function costPolicyRow(service, lang, detail) {
  const names = {
    zh: { hotel: "酒店", vehicle: "用车", ticket: "门票", guide: "导游", meal: "用餐", traffic: "大交通", other: "其他" },
    en: { hotel: "Hotel", vehicle: "Chartered Vehicle", ticket: "Entrance Ticket", guide: "Tour Guide", meal: "Food", traffic: "Transportation", other: "Other Fees" },
  };
  if (lang === "zh") return { item: names.zh[service], included: detail.zhIncluded, excluded: detail.zhExcluded };
  return { item: names.en[service], included: detail.enIncluded, excluded: detail.enExcluded };
}

function localizeDay(day, lang) {
  if (lang === "zh") {
    return { date: day.date, city: day.city, overview: day.overview, detail: day.detail };
  }
  const city = translate(day.city, lang) || fallbackCity(lang);
  const attractions = extractAttractions(`${day.overview} ${day.detail}`);
  const translatedAttractions = attractions.map((name) => translate(name, lang)).filter((name) => name && !containsChinese(name));
  const overview = translatedAttractions.length ? translatedAttractions.join(" · ") : fallbackOverview(city, lang);
  const detailTemplates = {
    en: translatedAttractions.length ? `Enjoy a private tour in ${city}, covering ${translatedAttractions.join(", ")} with a comfortable pace.` : `Enjoy a private tour in ${city} based on the confirmed itinerary.`,
    ar: translatedAttractions.length ? `استمتع بجولة خاصة في ${city} تشمل ${translatedAttractions.join("، ")} بوتيرة مريحة.` : `استمتع بجولة خاصة في ${city} وفق البرنامج المؤكد.`,
    fr: translatedAttractions.length ? `Profitez d'une visite privée à ${city}, avec ${translatedAttractions.join(", ")}, à un rythme confortable.` : `Profitez d'une visite privée à ${city} selon l'itinéraire confirmé.`,
    es: translatedAttractions.length ? `Disfrute de un tour privado en ${city}, visitando ${translatedAttractions.join(", ")} con un ritmo cómodo.` : `Disfrute de un tour privado en ${city} según el itinerario confirmado.`,
  };
  return {
    date: day.date,
    city: safeLocalized(city, lang, fallbackCity(lang)),
    overview: safeLocalized(overview, lang, fallbackOverview(city, lang)),
    detail: safeLocalized(detailTemplates[lang] || detailTemplates.en, lang, detailTemplates.en),
  };
}

function extractAttractions(text) {
  const standardized = standardizeEnglishAttractions(text);
  const names = [
    ...Object.keys(resources.tickets),
    "故宫博物院", "八达岭长城", "长城", "天安门广场", "景山", "胡同", "南京路", "古城墙", "大熊猫基地", "武侯祠", "洪崖洞", "张家界国家森林公园", "陆家嘴", "城隍庙", "南京东路", "田子坊", "老洋房街区", "万国建筑群", "黄浦江夜景", "东方明珠",
  ];
  return unique(names.filter((name) => String(standardized).includes(name)));
}

function standardizeEnglishAttractions(text) {
  let result = String(text || "");
  englishAttractionAliases
    .sort((a, b) => b[0].length - a[0].length)
    .forEach(([alias, standard]) => {
      result = result.replace(new RegExp(`\\b${escapeRegExp(alias)}\\b`, "gi"), standard);
    });
  return result;
}

function escapeRegExp(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsChinese(text) {
  return /[\u4e00-\u9fa5]/.test(String(text || ""));
}

function safeLocalized(text, lang, fallback) {
  if (lang === "zh") return text;
  return !String(text || "").trim() || containsChinese(text) ? fallback : text;
}

function fallbackCity(lang) {
  return { en: "China", ar: "الصين", fr: "Chine", es: "China" }[lang] || "China";
}

function fallbackOverview(city, lang) {
  const safeCity = city || fallbackCity(lang);
  return {
    en: `${safeCity} Highlights`,
    ar: `أبرز معالم ${safeCity}`,
    fr: `Temps forts de ${safeCity}`,
    es: `Lugares destacados de ${safeCity}`,
  }[lang] || `${safeCity} Highlights`;
}

function itemizedPriceHtml(lang) {
  const t = i18n[lang] || i18n.zh;
  const rows = serviceEnabledList().map((service) => {
    const sell = serviceSell(service);
    return sell > 0 ? `<tr><td>${t.items[service] || serviceLabels[service]}</td><td>${money(sell)}</td></tr>` : "";
  }).join("");
  return `<div class="proposal-block"><h4>${t.itemized}</h4><table class="simple-table"><tbody>${rows || `<tr><td>${t.noItemized}</td><td>-</td></tr>`}</tbody></table></div>`;
}

function contactHtml(lang) {
  const t = i18n[lang] || i18n.zh;
  const blocks = [];
  const whatsapp = $("#contactWhatsappValue")?.value.trim();
  const wechat = $("#contactWechatValue")?.value.trim();
  if ($("#contactWhatsapp").checked) {
    blocks.push(`<div class="contact-card"><strong>WhatsApp</strong><span>${escapeHtml(whatsapp || (lang === "zh" ? "由定制师配置" : "To be configured"))}</span></div>`);
  }
  if ($("#contactWechat").checked) {
    blocks.push(`<div class="contact-card"><strong>${lang === "zh" ? "微信" : "WeChat"}</strong><span>${escapeHtml(wechat || (lang === "zh" ? "由定制师配置" : "To be configured"))}</span></div>`);
  }
  if ($("#contactEmail").checked) blocks.push(`<div class="contact-card"><strong>Email</strong><span>youyixing2025@163.com</span></div>`);
  return blocks.length ? `<div class="proposal-block"><h4>${t.contact}</h4><div class="contact-grid">${blocks.join("")}</div></div>` : "";
}

function renderEnglishWarning() {
  const warning = $("#englishWarning");
  if (!warning) return;
  const shouldCheck = $("#outputLang")?.value === "en" && Boolean($("#proposalContent")?.innerText.trim());
  const hasChinese = shouldCheck && containsChinese($("#proposal")?.innerText || "");
  warning.classList.toggle("hidden", !hasChinese);
}

function renderProposalAssets() {
  const wrap = $("#proposalAssets");
  ensureProposalAssets();
  state.proposalAssets = state.proposalAssets.map(normalizeProposalAsset);
  renderAssetSummary();
  const manager = $("#proposalAssetManager");
  if (manager) manager.classList.toggle("hidden", !state.assetManagerOpen);
  const toggle = $("#toggleAssetManager span");
  if (toggle) toggle.textContent = state.assetManagerOpen ? "收起管理" : "展开管理";
  if (!wrap) return;
  if (!state.assetManagerOpen) {
    wrap.innerHTML = "";
    renderXiaoyiContext();
    return;
  }
  wrap.innerHTML = state.proposalAssets.map((asset, index) => `
    <div class="asset-card ${asset.confirmed ? "confirmed" : ""} ${asset.url ? "" : "missing"}">
      <div class="asset-thumb">${asset.url ? `<img src="${escapeHtml(asset.url)}" alt="${escapeHtml(asset.name)}" />` : `<span>待补图</span>`}</div>
      <div>
        <strong>${escapeHtml(asset.name)}</strong>
        <span>${escapeHtml(asset.category || asset.type)} · ${asset.confirmed ? "已确认" : "待确认"}${asset.isCover ? " · 封面图" : ""}</span>
        <p>${escapeHtml(asset.note || "")}</p>
        <div class="asset-inline-controls">
          <label>分类<select data-asset-category="${index}">${assetCategories().map((item) => `<option ${asset.category === item ? "selected" : ""}>${item}</option>`).join("")}</select></label>
          <label><input type="checkbox" data-asset-use="${index}" ${asset.useInProposal ? "checked" : ""} /> 用于提案</label>
          <label><input type="checkbox" data-asset-cover="${index}" ${asset.isCover ? "checked" : ""} /> 封面</label>
        </div>
      </div>
      <div class="asset-card-actions">
        ${asset.url ? `<a class="secondary-btn" href="${escapeHtml(asset.url)}" target="_blank" rel="noopener">查看</a>` : ""}
        <label class="secondary-btn mini-upload"><input type="file" accept="image/*" hidden data-replace-asset="${index}" />替换</label>
        <button class="secondary-btn" data-confirm-asset="${index}">${asset.confirmed ? "取消确认" : "确认"}</button>
        <button class="ghost-btn" data-remove-asset="${index}">删除</button>
      </div>
    </div>
  `).join("") || `<div class="empty">暂无图片素材。生成行程后会自动列出酒店和景点待补图。</div>`;
  $$("[data-confirm-asset]").forEach((btn) => btn.addEventListener("click", () => {
    const asset = state.proposalAssets[Number(btn.dataset.confirmAsset)];
    if (asset) asset.confirmed = !asset.confirmed;
    invalidateProposalConfirmation();
    renderProposalAssets();
  }));
  $$("[data-remove-asset]").forEach((btn) => btn.addEventListener("click", () => {
    state.proposalAssets.splice(Number(btn.dataset.removeAsset), 1);
    invalidateProposalConfirmation();
    renderProposalAssets();
  }));
  $$("[data-asset-category]").forEach((select) => select.addEventListener("change", () => {
    const asset = state.proposalAssets[Number(select.dataset.assetCategory)];
    if (asset) asset.category = select.value;
    invalidateProposalConfirmation();
    renderProposalAssets();
  }));
  $$("[data-asset-use]").forEach((input) => input.addEventListener("change", () => {
    const asset = state.proposalAssets[Number(input.dataset.assetUse)];
    if (asset) asset.useInProposal = input.checked;
    invalidateProposalConfirmation();
    renderProposalAssets();
  }));
  $$("[data-asset-cover]").forEach((input) => input.addEventListener("change", () => {
    const asset = state.proposalAssets[Number(input.dataset.assetCover)];
    if (asset) {
      if (input.checked) state.proposalAssets.forEach((item) => { item.isCover = false; });
      asset.isCover = input.checked;
      asset.useInProposal = true;
    }
    invalidateProposalConfirmation();
    applyProposalCoverImage();
    renderProposalAssets();
  }));
  $$("[data-replace-asset]").forEach((input) => input.addEventListener("change", async () => {
    const file = input.files?.[0];
    const asset = state.proposalAssets[Number(input.dataset.replaceAsset)];
    if (!file || !asset) return;
    asset.url = await fileToDataUrl(file);
    asset.name = file.name;
    asset.confirmed = false;
    asset.note = "已替换为本地上传图片，进入客户提案前需确认。";
    invalidateProposalConfirmation();
    applyProposalCoverImage();
    renderProposalAssets();
  }));
  renderXiaoyiContext();
  renderIcons();
}

function ensureProposalAssets() {
  const names = extractProposalAssetNames();
  const existing = new Set(state.proposalAssets.map((asset) => `${asset.type}:${asset.name}`));
  names.forEach((asset) => {
    const key = `${asset.type}:${asset.name}`;
    if (!existing.has(key)) state.proposalAssets.push(normalizeProposalAsset(asset));
  });
}

function normalizeProposalAsset(asset) {
  const type = asset.type || "其他素材";
  return {
    id: asset.id || `asset_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    type,
    category: asset.category || proposalAssetCategoryFromType(type),
    name: asset.name || "未命名素材",
    url: asset.url || "",
    confirmed: Boolean(asset.confirmed),
    useInProposal: asset.useInProposal !== false,
    isCover: Boolean(asset.isCover),
    source: asset.source || "product_library",
    note: asset.note || "",
  };
}

function proposalAssetCategoryFromType(type) {
  if (type === "酒店") return "酒店参考图";
  if (type === "景点") return "景点图片";
  if (type === "餐") return "餐厅图片";
  if (type === "用户上传") return "待分类";
  return "其他素材";
}

function assetCategories() {
  return ["待分类", "封面图", "酒店参考图", "景点图片", "餐厅图片", "行程氛围图", "其他素材"];
}

function renderAssetSummary() {
  const uploaded = state.proposalAssets.filter((asset) => asset.url).length;
  const confirmed = state.proposalAssets.filter((asset) => asset.confirmed && asset.useInProposal).length;
  const unclassified = state.proposalAssets.filter((asset) => asset.url && (!asset.category || asset.category === "待分类")).length;
  const missing = state.proposalAssets.filter((asset) => !asset.url).length;
  if ($("#assetSummaryUploaded")) $("#assetSummaryUploaded").textContent = uploaded;
  if ($("#assetSummaryConfirmed")) $("#assetSummaryConfirmed").textContent = confirmed;
  if ($("#assetSummaryUnclassified")) $("#assetSummaryUnclassified").textContent = unclassified;
  if ($("#assetSummaryMissing")) $("#assetSummaryMissing").textContent = missing;
}

function toggleAssetManager(force) {
  state.assetManagerOpen = typeof force === "boolean" ? force : !state.assetManagerOpen;
  renderProposalAssets();
}

function clearUnusedProposalAssets() {
  const before = state.proposalAssets.length;
  state.proposalAssets = state.proposalAssets.filter((asset) => asset.confirmed || asset.useInProposal || !asset.url);
  invalidateProposalConfirmation();
  renderProposalAssets();
  addXiaoyiMessage("assistant", `已清理 ${before - state.proposalAssets.length} 张未使用图片。`);
}

function extractProposalAssetNames() {
  const quote = activeQuote()?.data || emptyQuoteData();
  const ticketAssets = unique(state.itinerary.flatMap((day) => extractAttractions(`${day.overview} ${day.detail}`))).map((name) => ({
    type: "景点",
    name,
    url: firstImageUrlForName(name),
    confirmed: Boolean(firstImageUrlForName(name)),
    note: firstImageUrlForName(name) ? "来自产品库图片" : "待补图，可上传或粘贴图片 URL。",
  }));
  const hotelAssets = unique((quote.hotel || []).flatMap((row) => (row.rooms || []).map((room) => room.hotelName).filter(Boolean))).map((name) => ({
    type: "酒店",
    name,
    url: firstImageUrlForName(name),
    confirmed: Boolean(firstImageUrlForName(name)),
    note: firstImageUrlForName(name) ? "来自产品库图片" : "真实酒店图片待人工补充，不能用 AI 乱生成。",
  }));
  return [...ticketAssets, ...hotelAssets];
}

function firstImageUrlForName(name) {
  const text = String(name || "");
  const all = [
    ...state.productCatalog.tickets.map((item) => ({ name: item.scenicName, raw: item })),
    ...state.productCatalog.hotels.map((item) => ({ name: item.hotelName, raw: item })),
  ];
  const matched = all.find((item) => item.name && (text.includes(item.name) || item.name.includes(text)));
  const urls = matched?.raw?.image_urls || matched?.raw?.imageUrls || matched?.raw?.images || [];
  return Array.isArray(urls) ? (urls[0] || "") : "";
}

function addProposalAssetFromUrl() {
  const input = $("#assetUrlInput");
  const url = input?.value.trim();
  if (!url) return;
  state.proposalAssets.unshift({
    id: `asset_${Date.now()}`,
    type: "用户上传",
    category: "待分类",
    name: "手动补充图片",
    url,
    confirmed: false,
    useInProposal: true,
    isCover: false,
    source: "manual_url",
    note: "来自 OP 粘贴的图片 URL，进入客户提案前需确认。",
  });
  if (input) input.value = "";
  invalidateProposalConfirmation();
  renderProposalAssets();
}

function handleProposalAssetUpload(event) {
  const files = Array.from(event.target.files || []);
  files.forEach((file) => {
    state.proposalAssets.unshift(normalizeProposalAsset({
      type: "用户上传",
      category: "待分类",
      name: file.name,
      url: URL.createObjectURL(file),
      confirmed: false,
      useInProposal: true,
      source: "manual_upload",
      note: "本地上传图片，进入客户提案前需确认。",
    }));
  });
  event.target.value = "";
  invalidateProposalConfirmation();
  renderProposalAssets();
}

async function handleExportImage() {
  if (!canExportProposal()) return;
  if (!window.html2canvas) {
    alert("导出组件还在加载，请稍后再试。");
    return;
  }
  const canvas = await html2canvas($("#proposal"), { scale: 2, useCORS: true });
  const link = document.createElement("a");
  link.download = `travel-proposal-${Date.now()}.png`;
  link.href = canvas.toDataURL("image/png");
  link.click();
}

async function handleExportPdf() {
  if (!canExportProposal()) return;
  if (!window.html2canvas || !window.jspdf?.jsPDF) {
    alert("PDF 导出组件还在加载，请稍后再试。");
    return;
  }
  const proposal = $("#proposal");
  const canvas = await html2canvas(proposal, { scale: 2, useCORS: true });
  const imgData = canvas.toDataURL("image/png");
  const pdf = new window.jspdf.jsPDF("p", "mm", "a4");
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const imgWidth = pageWidth;
  const imgHeight = (canvas.height * imgWidth) / canvas.width;
  let heightLeft = imgHeight;
  let position = 0;
  pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
  heightLeft -= pageHeight;
  while (heightLeft > 0) {
    position = heightLeft - imgHeight;
    pdf.addPage();
    pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
    heightLeft -= pageHeight;
  }
  pdf.save(`travel-proposal-${Date.now()}.pdf`);
}

function convertToOrder() {
  if (!activeQuote()?.data?.vehicle?.length && state.routeConfirmed) buildQuote({ auto: true });
  const totals = calcTotals();
  const d = getDemand();
  const quote = activeQuote();
  const projectId = state.currentProjectId || $("#projectId").textContent;
  const orderId = String(projectId || `QP-${Date.now()}`).replace("QP", "OD");
  state.order = {
    id: orderId,
    projectId,
    customerName: d.actualCustomerName || d.clientName,
    country: d.country,
    startDate: d.startDate,
    days: d.serviceDays,
    people: d.people,
    cities: d.cities.join("、"),
    amount: totals.sell,
    currency: $("#currency")?.value || "CNY",
    quoteVersion: quote?.name || $("#quoteVersion")?.selectedOptions?.[0]?.textContent || "报价 V1",
    status: "已成交待操作",
    createdAt: new Date().toISOString(),
  };
  state.orders = [state.order, ...state.orders.filter((item) => item.id !== state.order.id)];
  $("#orderArchive").className = "archive-list";
  $("#orderArchive").innerHTML = `<div class="archive-item"><strong>${state.order.id}</strong><span>已成交 · ${money(state.order.amount)} · 已进入操作排团</span></div>`;
  $("#followStatus").value = "已成交";
  $("#projectStatus").textContent = "已成交待操作";
  $("#projectStatus").className = "status ok";
  updateCurrentProject("已成交待操作");
  activeQuote().final = true;
  saveQuoteVersionMeta(true);
  saveOrderState();
  saveCurrentProjectSnapshot();
  renderOrders();
  showProjectDashboard();
  alert(`已成交并生成订单 ${state.order.id}，项目已返回报价列表。`);
}

function renderOrders() {
  const panel = $("#ordersPanel");
  if (!panel) return;
  const orders = state.orders || [];
  if (!orders.length) {
    panel.className = "panel empty";
    panel.textContent = "暂无成交订单。";
    return;
  }
  panel.className = "panel";
  panel.innerHTML = tableWrap(
    ["订单编号", "客户名称", "国家", "出行日期", "天数", "人数", "城市", "成交金额", "币种", "关联报价版本", "状态", "创建时间", "操作"],
    orders.map((order) => [
      escapeHtml(order.id),
      escapeHtml(order.customerName),
      escapeHtml(order.country),
      escapeHtml(order.startDate),
      escapeHtml(order.days),
      escapeHtml(order.people),
      escapeHtml(order.cities),
      money(order.amount),
      escapeHtml(order.currency),
      escapeHtml(order.quoteVersion),
      escapeHtml(order.status),
      escapeHtml(new Date(order.createdAt).toLocaleString("zh-CN", { hour12: false })),
      `<button class="secondary-btn" data-open-project="${escapeHtml(order.projectId)}">返回报价项目</button>`,
    ]),
    `<tr><td colspan="13">暂无成交订单。</td></tr>`,
    "wide-product-table"
  );
  $$("[data-open-project]").forEach((btn) => btn.addEventListener("click", () => {
    switchModule("quote");
    openProject(btn.dataset.openProject);
  }));
}

function renderArchive() {
  $("#quoteArchive").innerHTML = state.quoteVersions.map((version, index) => {
    const active = index === state.activeQuote ? "当前" : "历史";
    const meta = [
      active,
      version.status,
      version.generatedAt ? new Date(version.generatedAt).toLocaleString("zh-CN", { hour12: false }) : "",
      version.language ? `语言 ${version.language}` : "",
      version.totalPrice ? `总价 ${money(version.totalPrice)}` : "",
      version.averagePrice ? `人均 ${money(version.averagePrice)}` : "",
      version.grossMargin !== undefined ? `毛利率 ${version.grossMargin}%` : "",
      version.confirmed ? "已确认" : "未确认",
      version.final ? "最终成交版" : "",
    ].filter(Boolean).join(" · ");
    return `<div class="archive-item"><strong>${version.name}</strong><span>${meta}</span></div>`;
  }).join("");
}

function canExportProposal() {
  if (!$("#proposalContent")?.innerHTML.trim()) {
    alert("请先生成客户方案预览。");
    return false;
  }
  if (!state.proposalConfirmed) {
    alert("请先确认客户方案，再下载 PDF 或导出图片。");
    renderProposalGuard();
    return false;
  }
  return true;
}

function money(value) {
  if (value === "" || value == null || Number.isNaN(Number(value))) return "-";
  const code = $("#currency")?.value || "CNY";
  const rate = dailyRates[code];
  const converted = number(value) / rate.rate;
  if (code === "AED") return `${rate.symbol}${Math.round(converted).toLocaleString("en-US")}`;
  return `${rate.symbol}${Math.round(converted).toLocaleString(code === "CNY" ? "zh-CN" : "en-US")}`;
}
function resourceCost(table, city, key) {
  return table[city]?.[key] ?? "";
}

function lookupResourceCost(type, city, key, fallbackTable, fallbackKey) {
  if (type === "vehicle") {
    const lookup = lookupVehicleResource({ city, vehicleType: normalizeVehicleType(key), model: fallbackKey || key, text: key });
    return withLegacyFallback(lookup, fallbackTable ? resourceCost(fallbackTable, city, legacyVehicleKey(fallbackKey || key)) : "", "用车");
  }
  if (type === "guide") {
    const lookup = lookupGuideResource(city, fallbackKey || key, getDemandSafe().startDate);
    return withLegacyFallback(lookup, fallbackTable ? resourceCost(fallbackTable, city, fallbackKey || key) : "", "导游");
  }
  if (type === "hotel") {
    const lookup = lookupHotelResource({ city, star: fallbackKey || key, roomType: "" });
    return withLegacyFallback(lookup, fallbackTable ? resourceCost(fallbackTable, city, fallbackKey || key) : "", "酒店");
  }
  if (type === "meal") {
    return lookupMealResource({ city, meal: key, demand: getDemandSafe() });
  }
  const fallback = fallbackTable ? resourceCost(fallbackTable, city, fallbackKey || key) : "";
  return { ...pendingResult(fallback !== "" ? `旧标准价 / ${type}` : "待补价"), cost: fallback, sourceType: fallback !== "" ? "旧标准价" : "待补价" };
}

function lookupTicketCost(name, city, date = getDemandSafe().startDate, ticketType = "景区门票") {
  const ticket = lookupTicketResource(name, city, date, ticketType);
  if (ticket) {
    return {
      adultCost: ticket.cost,
      childCost: ticket.childCost,
      source: ticket.cost === "" ? `待补价 / ${ticket.source}` : ticket.source,
      sourceType: ticket.cost === "" ? "待补价" : ticket.sourceType,
      sourceProductId: ticket.sourceProductId,
      sourceResourceId: ticket.sourceResourceId,
      sourceName: ticket.sourceName,
      matchStatus: ticket.matchStatus,
      matchConfidence: ticket.matchConfidence,
      isFree: ticket.isFree,
      ticketType: ticket.resource?.raw?.ticketType || ticketType,
      candidates: ticket.candidates || [],
      resource: ticket.resource,
    };
  }
  const experience = lookupExperienceResource({ city, name, ticketType });
  if (experience?.resource && experience.sourceType !== "待补价" && experience.matchStatus !== "unmatched") {
    return {
      adultCost: experience.cost,
      childCost: experience.childCost,
      source: experience.cost === "" ? `待补成本 / ${experience.source}` : experience.source,
      sourceType: experience.cost === "" ? "待补价" : experience.sourceType,
      sourceProductId: experience.sourceProductId,
      sourceResourceId: experience.sourceResourceId,
      sourceName: experience.sourceName,
      matchStatus: experience.matchStatus,
      matchConfidence: experience.matchConfidence,
      isFree: experience.isFree,
      ticketType: experience.resource?.raw?.ticketType || ticketType,
      candidates: experience.candidates || [],
      resource: experience.resource,
    };
  }
  const catalog = state.productCatalog.tickets.find((ticket) => {
    const sameCity = ticket.city === city || !city;
    return sameCity && sameTicketName(ticket.scenicName, name) && normalizeTicketType(ticket.ticketType) === normalizeTicketType(ticketType);
  }) || state.productCatalog.tickets.find((ticket) => {
    const sameCity = ticket.city === city || !city;
    return sameCity && sameTicketName(ticket.scenicName, name);
  });
  if (catalog) {
    const adultCost = ticketAdultCost(catalog, date);
    const childCost = ticketChildCost(catalog, date);
    return {
      adultCost,
      childCost,
      source: adultCost === "" && childCost === "" ? "产品库待补价" : `产品库 / ${catalog.ticketType || ticketType}`,
      sourceType: adultCost === "" ? "待补价" : "产品库",
      sourceProductId: "",
      sourceResourceId: "",
      sourceName: catalog.scenicName,
      matchStatus: adultCost === "" && !isFreeTicket(catalog, adultCost) ? "need_price" : "matched",
      matchConfidence: "medium",
      isFree: isFreeTicket(catalog, adultCost),
      ticketType: catalog.ticketType,
      candidates: [],
    };
  }
  const standard = resources.tickets[name];
  const aliasStandardName = Object.keys(resources.tickets).find((item) => sameTicketName(item, name));
  const standardRow = standard || resources.tickets[aliasStandardName];
  if (standardRow) {
    const free = standardRow.isFree || Number(standardRow.adult) === 0;
    const sourceName = aliasStandardName || name;
    return {
      adultCost: standardRow.adult ?? "",
      childCost: standardRow.child ?? "",
      isFree: free,
      matchStatus: standardRow.adult === "" && !free ? "need_price" : "matched",
      matchConfidence: "medium",
      source: standardRow.adult === "" && !free
        ? `待补成本：真实产品库未找到「${sourceName}」成本，系统仅识别到景点名`
        : (free ? "系统兜底 / 免费景点 / 待 OP 确认" : "系统兜底价 / 待 OP 确认真实产品库"),
      sourceType: standardRow.adult === "" && !free ? "待补价" : "系统兜底",
      sourceProductId: "",
      sourceResourceId: "",
      sourceName,
      ticketType,
      candidates: [],
    };
  }
  return {
    adultCost: "",
    childCost: "",
    source: `待补成本：真实产品库未找到「${name}」门票资源`,
    sourceType: "待补价",
    sourceProductId: "",
    sourceResourceId: "",
    sourceName: name,
    matchStatus: "unmatched",
    matchConfidence: "low",
    ticketType,
    candidates: [],
  };
}

function mergeSources(...sources) {
  return unique(sources.filter(Boolean).flatMap((source) => String(source).split(" / "))).join(" / ");
}

function firstFilled(...values) {
  const found = values.find((value) => value !== "" && value != null);
  return found ?? "";
}

function normalizeTicketText(value) {
  return String(value || "").replace(/\s+/g, "").replace(/[（）()《》“”"']/g, "");
}

function ticketAliases(name) {
  const normalized = normalizeTicketText(name);
  const hits = [];
  Object.entries(attractionAliases).forEach(([canonical, aliases]) => {
    const group = [canonical, ...aliases];
    if (group.some((item) => normalizeTicketText(item) === normalized || normalizeTicketText(item).includes(normalized) || normalized.includes(normalizeTicketText(item)))) {
      hits.push(...group);
    }
  });
  return unique(hits);
}

function sameTicketName(a, b) {
  const leftGroup = unique([a, ...ticketAliases(a)].map(normalizeTicketText));
  const rightGroup = unique([b, ...ticketAliases(b)].map(normalizeTicketText));
  return leftGroup.some((left) => rightGroup.some((right) => left === right || left.includes(right) || right.includes(left)));
}

function ticketCandidates(city) {
  const rows = [];
  Object.entries(resources.tickets).forEach(([name, info]) => {
    if (!city || info.city === city || info.city === "通用") rows.push({ name, alias: name });
  });
  quoteResources().filter((item) => ["ticket", "experience"].includes(item.type) && sameCity(item, city)).forEach((item) => {
    const displayName = item.scenicName || item.experienceName || item.name;
    rows.push({ name: displayName, alias: displayName, ticketType: item.raw?.ticketType || item.ticketType });
    rows.push({ name: displayName, alias: shortTicketName(displayName), ticketType: item.raw?.ticketType || item.ticketType });
    (item.tags || []).forEach((tag) => rows.push({ name: displayName, alias: tag, ticketType: item.raw?.ticketType || item.ticketType }));
  });
  state.resourceItems.filter((item) => item.type === "ticket" && (!city || item.city === city || item.city === "通用")).forEach((item) => {
    rows.push({ name: item.name, alias: item.name });
    (item.tags || []).forEach((tag) => rows.push({ name: item.name, alias: tag }));
  });
  state.productCatalog.tickets.filter((item) => !city || item.city === city).forEach((item) => {
    rows.push({ name: item.scenicName, alias: item.scenicName });
    rows.push({ name: item.scenicName, alias: shortTicketName(item.scenicName) });
    ticketAliases(item.scenicName).forEach((alias) => rows.push({ name: item.scenicName, alias }));
  });
  return rows.filter((item) => normalizeTicketText(item.alias).length >= 2);
}

function shortTicketName(name) {
  return String(name || "").replace(/博物院|博物馆|景区|风景区|国家森林公园/g, (suffix) => suffix === "国家森林公园" ? suffix : "").trim() || name;
}

function detectTickets(text, city) {
  const normalizedText = normalizeTicketText(text);
  const cityNames = new Set(["北京", "上海", "杭州", "西安", "广州", "深圳", "成都", "重庆", "苏州", "桂林", "张家界", "昆明", "丽江", "大理", city].filter(Boolean).map(normalizeTicketText));
  const candidates = ticketCandidates(city).sort((a, b) => b.alias.length - a.alias.length);
  const hits = candidates
    .filter((candidate) => normalizedText.includes(normalizeTicketText(candidate.alias)))
    .filter((candidate) => !cityNames.has(normalizeTicketText(candidate.name)) && !cityNames.has(normalizeTicketText(candidate.alias)))
    .sort((a, b) => normalizedText.indexOf(normalizeTicketText(a.alias)) - normalizedText.indexOf(normalizeTicketText(b.alias)))
    .map((candidate) => candidate.name);
  const inferred = inferTicketNamesFromText(text, city).filter((name) => !hits.some((hit) => sameTicketName(hit, name)));
  return dedupeTicketNames([...hits, ...inferred]);
}

function dedupeTicketNames(names = []) {
  const result = [];
  names.filter(Boolean).forEach((name) => {
    const index = result.findIndex((existing) => sameTicketName(existing, name));
    if (index >= 0) {
      if (normalizeTicketText(name).length > normalizeTicketText(result[index]).length) result[index] = name;
      return;
    }
    result.push(name);
  });
  return result;
}

function inferTicketNamesFromText(text, city) {
  const stopWords = ["机场", "酒店", "入住", "退房", "自由活动", "自由休闲", "自由采购", "购物", "返程", "送机", "接机", "接站", "送站", "用餐", "午餐", "晚餐", "早餐", "高铁", "火车", "飞机", "航班", "车程", "休息", "拍照时间", "根据客人需求"];
  const parts = String(text || "")
    .replace(/day\s*\d+|第\s*[一二三四五六七八九十百\d]+\s*天/gi, " ")
    .split(/[，,。；;、|｜\n]/)
    .flatMap((part) => part.split(/[+＋]/))
    .map((part) => cleanSegment(part).replace(/^(上午|下午|晚上|早上|中午|全天|前往|游览|参观|打卡|欣赏|体验|乘机前往|乘车前往|抵达|返回|安排)/, "").trim())
    .filter(Boolean);
  return unique(parts.filter((part) => {
    const compact = normalizeTicketText(part);
    if (compact.length < 2 || compact.length > 22) return false;
    if (stopWords.some((word) => part.includes(word))) return false;
    if (city && compact === normalizeTicketText(city)) return false;
    return /(故宫|长城|兵马俑|博物馆|博物院|公园|国家森林|森林公园|景区|山|湖|塔|寺|园|庙|城|村|古镇|广场|石窟|陵|宫|洞|峡|茶园|祠|街区|古街)/.test(part);
  }));
}

function addDays(date, days) {
  const [year, month, day] = String(date || "2026-07-01").split("-").map(Number);
  const d = new Date(Date.UTC(year, month - 1, day + days));
  return d.toISOString().slice(0, 10);
}

function expandCities(cities, days) {
  const plan = [];
  const base = Math.floor(days / cities.length);
  let extra = days % cities.length;
  cities.forEach((city) => {
    const count = base + (extra-- > 0 ? 1 : 0);
    for (let i = 0; i < count; i += 1) plan.push(city);
  });
  return plan;
}

