function splitCities(value) {
  return value.split(/[、,，\s]+/).map((x) => x.trim()).filter(Boolean);
}

function stripLabel(value) {
  return String(value || "").replace(/^(行程概览|概览|overview|行程详情|详细行程|详情|detail|城市)[:：]\s*/i, "").trim();
}

function isDayStart(value) {
  return /^(day\s*\d+|d\s*\d+|第\s*[一二三四五六七八九十百\d]+\s*天)(?=\s|[:：|｜、.．\-—–]|$)/i.test(String(value || "").trim());
}

function removeDayMarker(value) {
  return String(value || "")
    .replace(/^(day\s*\d+|d\s*\d+)[:：\s|｜、.．\-—–]*/i, "")
    .replace(/^第\s*[一二三四五六七八九十百\d]+\s*天[:：\s|｜、.．\-—–]*/, "")
    .trim();
}

function splitItinerarySegments(value) {
  return String(value || "").split(/\s*[|｜]\s*/).map((part) => part.trim()).filter(Boolean);
}

function cleanSegment(value) {
  return stripLabel(value).replace(/^[|｜:：\s\-—–]+/, "").trim();
}

function labeledSegment(segments, pattern) {
  const raw = segments.find((part) => pattern.test(part));
  return raw ? stripLabel(raw) : "";
}

function isCityOnly(value) {
  const text = String(value || "").replace(/[→\-—到至]/g, " ").trim();
  const cities = text.split(/\s+/).filter(Boolean);
  return cities.length > 0 && cities.every((part) => Boolean(inferCity(part)));
}

function isDetailLike(value) {
  return /(上午|下午|晚上|早上|中午|全天|随后|之后|抵达|返回|前往|乘坐|入住|退房|安排|结束|游览|参观|打卡|欣赏|体验|用餐|午餐|晚餐|早餐|车程|小时|分钟|自由活动)/.test(value || "");
}

function summarizeFromDetail(detail) {
  const attractions = extractAttractions(detail || "");
  return attractions.slice(0, 4).join("、");
}

function normalizeOverview(value, city) {
  return cleanSegment(value).replace(new RegExp(`^${city}[→\\-—到至]?`, "u"), "").replace(/行程详情[:：]?.*$/u, "").trim();
}

function normalizeDetail(value, overview, city) {
  const detail = cleanSegment(value);
  if (detail && detail !== overview) return detail;
  return generateDetailFromOverview(overview, city);
}

function generateDetailFromOverview(overview, city) {
  const attractions = extractAttractions(overview);
  if (attractions.length) {
    return `根据当天节奏游览${attractions.join("、")}，由定制师按交通距离和预约时间调整参观顺序。`;
  }
  return `根据客人需求安排${city || "当地"}城市游览，并预留适当休息和拍照时间。`;
}

function inferCity(text) {
  return extractRouteCities(text)[0] || "";
}

function valueOrBlank(value) {
  return value === "" ? "" : Number(value);
}

function number(value) {
  return value === "" || value == null || Number.isNaN(Number(value)) ? 0 : Number(value);
}

function unique(values) {
  return Array.from(new Set(values.filter(Boolean)));
}

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[ch]));
}

